-- Aprenda se Divertindo · 125 · Simulados do fim de semana 21–22/11 (todas as trilhas)
-- Rode depois do 124-enem.sql. Cole tudo no SQL Editor e clique em Run.
-- Todos abrem no sábado, 21/11/2026, às 0h, e fecham no domingo, 22/11/2026, às 23h59.
--
-- PARTE 1 · Simulado 5 da Trilha Policial (NOVO, no nível do Simulado Desafio)
--   100 questões de A a E, estilo AOCP (Investigador PC-BA), 4 horas de prova.
--   Gerais (40): Português 10, Raciocínio Lógico 7, Informática 7, Atualidades 4, Igualdade Racial e de Gênero 4,
--   Medicina Legal 4, Legislação Geral (Lei Estadual 6.677/1994) 4. Específicos (60): Penal 10, Processo Penal 9,
--   Legislação Extravagante 9, Contabilidade 8, Constitucional 8, Administrativo 8, Estatística 8.
--   Gabarito equilibrado: 20 questões com cada letra (A a E), sem três letras iguais seguidas.
--   Rodar de novo atualiza as questões, desde que ninguém tenha começado.
--
-- PARTE 2 · Repetição das outras trilhas, com nome novo e alternativas embaralhadas
--   Enem, Fiscal, Tribunais e Administrativa viram "Simulado 2"; Saúde vira "Simulado 3" (repete o Simulado 1 · Saúde).
--   As questões são as do Simulado 1 de cada trilha, mas a ordem das alternativas (A a E) é sorteada de novo,
--   e o gabarito acompanha a troca. Rodar de novo não duplica nada.
--
-- PARTE 3 · Simulado 1 da Trilha Geral (NOVO)
--   60 questões de A a E, 3 horas de prova: Português 15, Raciocínio Lógico 12, Constitucional 11,
--   Administrativo 11, Informática 11. Gabarito equilibrado: 12 questões com cada letra.
--   Rodar de novo atualiza as questões, desde que ninguém tenha começado.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "Quando se fala em segurança pública, é comum que o debate se reduza a uma disputa entre dois polos: de um lado, os que reclamam mais rigor; de outro, os que denunciam excessos. Essa polarização, embora compreensível, empobrece a discussão, porque esconde uma pergunta anterior e mais incômoda: o que, afinal, faz uma investigação chegar a bom termo?\n\nOs números ajudam a desfazer algumas ilusões. Em boa parte do país, a taxa de esclarecimento de homicídios permanece baixa, e não por falta de leis severas. O que falta, quase sempre, é a capacidade de transformar um local de crime em prova: preservar vestígios, ouvir testemunhas enquanto a memória ainda é fresca, cruzar registros antes que se percam. Não se trata, portanto, de escolher entre rigor e garantias, mas de reconhecer que, sem método, nem um nem outras se realizam.\n\nHá, ainda, um efeito pouco lembrado. Cada crime não esclarecido ensina algo a quem o cometeu e a quem o presenciou: ao primeiro, que o risco compensa; ao segundo, que denunciar talvez não valha a pena. A impunidade, nesse sentido, não é apenas a ausência de uma punição; é a presença de uma lição — e das piores.", "enunciado": "De acordo com o texto, a polarização do debate sobre segurança pública é prejudicial porque", "opcoes": ["leva a sociedade a desconfiar dos números oficiais sobre homicídios.", "favorece apenas os que denunciam excessos, deixando sem voz os que pedem rigor.", "transforma garantias individuais em obstáculos intransponíveis à investigação.", "impede a aprovação de leis mais severas, que resolveriam a baixa taxa de esclarecimento.", "oculta uma questão prévia: o que efetivamente faz uma investigação ter êxito."], "gabarito": 4, "explicacao": "O 1º parágrafo diz que a polarização 'esconde uma pergunta anterior e mais incômoda: o que, afinal, faz uma investigação chegar a bom termo?'. O 2º parágrafo afirma que a baixa elucidação não decorre da falta de leis severas."}, {"materia": "port", "texto_base": "Quando se fala em segurança pública, é comum que o debate se reduza a uma disputa entre dois polos: de um lado, os que reclamam mais rigor; de outro, os que denunciam excessos. Essa polarização, embora compreensível, empobrece a discussão, porque esconde uma pergunta anterior e mais incômoda: o que, afinal, faz uma investigação chegar a bom termo?\n\nOs números ajudam a desfazer algumas ilusões. Em boa parte do país, a taxa de esclarecimento de homicídios permanece baixa, e não por falta de leis severas. O que falta, quase sempre, é a capacidade de transformar um local de crime em prova: preservar vestígios, ouvir testemunhas enquanto a memória ainda é fresca, cruzar registros antes que se percam. Não se trata, portanto, de escolher entre rigor e garantias, mas de reconhecer que, sem método, nem um nem outras se realizam.\n\nHá, ainda, um efeito pouco lembrado. Cada crime não esclarecido ensina algo a quem o cometeu e a quem o presenciou: ao primeiro, que o risco compensa; ao segundo, que denunciar talvez não valha a pena. A impunidade, nesse sentido, não é apenas a ausência de uma punição; é a presença de uma lição — e das piores.", "enunciado": "No trecho “Não se trata, portanto, de escolher entre rigor e garantias, mas de reconhecer que, sem método, nem um nem outras se realizam”, as expressões “um” e “outras” retomam, respectivamente,", "opcoes": ["“rigor” e “leis severas”.", "“testemunhas” e “registros”.", "“rigor” e “garantias”.", "“método” e “garantias”.", "“local de crime” e “prova”."], "gabarito": 2, "explicacao": "'Um' (masculino singular) retoma 'rigor'; 'outras' (feminino plural) retoma 'garantias'. A concordância de gênero e número confirma a referência."}, {"materia": "port", "texto_base": "Quando se fala em segurança pública, é comum que o debate se reduza a uma disputa entre dois polos: de um lado, os que reclamam mais rigor; de outro, os que denunciam excessos. Essa polarização, embora compreensível, empobrece a discussão, porque esconde uma pergunta anterior e mais incômoda: o que, afinal, faz uma investigação chegar a bom termo?\n\nOs números ajudam a desfazer algumas ilusões. Em boa parte do país, a taxa de esclarecimento de homicídios permanece baixa, e não por falta de leis severas. O que falta, quase sempre, é a capacidade de transformar um local de crime em prova: preservar vestígios, ouvir testemunhas enquanto a memória ainda é fresca, cruzar registros antes que se percam. Não se trata, portanto, de escolher entre rigor e garantias, mas de reconhecer que, sem método, nem um nem outras se realizam.\n\nHá, ainda, um efeito pouco lembrado. Cada crime não esclarecido ensina algo a quem o cometeu e a quem o presenciou: ao primeiro, que o risco compensa; ao segundo, que denunciar talvez não valha a pena. A impunidade, nesse sentido, não é apenas a ausência de uma punição; é a presença de uma lição — e das piores.", "enunciado": "O conector “portanto”, no segundo parágrafo, introduz uma ideia de", "opcoes": ["condição, indicando a hipótese em que a investigação teria êxito.", "oposição, pois contrasta o rigor das leis penais com as garantias individuais citadas antes.", "concessão, admitindo um argumento contrário para depois refutá-lo.", "explicação, justificando por que as leis brasileiras são severas.", "conclusão, extraída das constatações feitas antes sobre a falta de método."], "gabarito": 4, "explicacao": "'Portanto' é conjunção conclusiva: depois de mostrar que falta capacidade técnica (preservar vestígios, ouvir testemunhas), o autor conclui que não se trata de escolher entre rigor e garantias."}, {"materia": "port", "texto_base": "Quando se fala em segurança pública, é comum que o debate se reduza a uma disputa entre dois polos: de um lado, os que reclamam mais rigor; de outro, os que denunciam excessos. Essa polarização, embora compreensível, empobrece a discussão, porque esconde uma pergunta anterior e mais incômoda: o que, afinal, faz uma investigação chegar a bom termo?\n\nOs números ajudam a desfazer algumas ilusões. Em boa parte do país, a taxa de esclarecimento de homicídios permanece baixa, e não por falta de leis severas. O que falta, quase sempre, é a capacidade de transformar um local de crime em prova: preservar vestígios, ouvir testemunhas enquanto a memória ainda é fresca, cruzar registros antes que se percam. Não se trata, portanto, de escolher entre rigor e garantias, mas de reconhecer que, sem método, nem um nem outras se realizam.\n\nHá, ainda, um efeito pouco lembrado. Cada crime não esclarecido ensina algo a quem o cometeu e a quem o presenciou: ao primeiro, que o risco compensa; ao segundo, que denunciar talvez não valha a pena. A impunidade, nesse sentido, não é apenas a ausência de uma punição; é a presença de uma lição — e das piores.", "enunciado": "Considere o período: “Cada crime não esclarecido ensina algo a quem o cometeu e a quem o presenciou”. Sobre ele, é correto afirmar que", "opcoes": ["o verbo “ensinar” tem dois complementos: “algo” (objeto direto) e “a quem o cometeu e a quem o presenciou” (objeto indireto).", "o pronome “o”, em “o cometeu”, retoma “algo” e funciona como objeto indireto.", "o verbo “presenciar” é transitivo indireto e, por isso, exige a preposição “a”.", "o sujeito da oração principal é indeterminado, marcado pela ausência de agente explícito.", "“não esclarecido” é oração subordinada adverbial reduzida de particípio, com valor causal, que explica por que o crime ensina algo a quem o cometeu."], "gabarito": 0, "explicacao": "Ensinar algo (OD) a alguém (OI). O pronome 'o' retoma 'crime' e é objeto direto de 'cometeu' e de 'presenciou'. 'Não esclarecido' é adjunto adnominal. O sujeito é 'Cada crime não esclarecido'."}, {"materia": "port", "texto_base": "Quando se fala em segurança pública, é comum que o debate se reduza a uma disputa entre dois polos: de um lado, os que reclamam mais rigor; de outro, os que denunciam excessos. Essa polarização, embora compreensível, empobrece a discussão, porque esconde uma pergunta anterior e mais incômoda: o que, afinal, faz uma investigação chegar a bom termo?\n\nOs números ajudam a desfazer algumas ilusões. Em boa parte do país, a taxa de esclarecimento de homicídios permanece baixa, e não por falta de leis severas. O que falta, quase sempre, é a capacidade de transformar um local de crime em prova: preservar vestígios, ouvir testemunhas enquanto a memória ainda é fresca, cruzar registros antes que se percam. Não se trata, portanto, de escolher entre rigor e garantias, mas de reconhecer que, sem método, nem um nem outras se realizam.\n\nHá, ainda, um efeito pouco lembrado. Cada crime não esclarecido ensina algo a quem o cometeu e a quem o presenciou: ao primeiro, que o risco compensa; ao segundo, que denunciar talvez não valha a pena. A impunidade, nesse sentido, não é apenas a ausência de uma punição; é a presença de uma lição — e das piores.", "enunciado": "No último parágrafo, o autor emprega o travessão em “é a presença de uma lição — e das piores” para", "opcoes": ["substituir os dois-pontos que anunciariam uma enumeração.", "isolar um vocativo, dirigindo-se diretamente ao leitor.", "introduzir a fala de um interlocutor que discorda da tese do texto.", "marcar uma retificação, pois o autor desmente a ideia de que a impunidade seja apenas a ausência de punição.", "destacar um acréscimo enfático que intensifica a avaliação negativa da impunidade."], "gabarito": 4, "explicacao": "O travessão isola um acréscimo enfático ('e das piores'), que reforça a avaliação: a impunidade ensina uma lição ruim."}, {"materia": "port", "texto_base": "O depoimento de uma testemunha costuma ser tratado como se fosse uma gravação: bastaria apertar o botão certo para que a cena retornasse intacta. A psicologia do testemunho mostra que não é assim. A memória não arquiva fatos; reconstrói-os a cada vez que é acessada, e cada reconstrução pode incorporar elementos que não estavam lá — uma sugestão do entrevistador, uma notícia lida depois, a própria expectativa de quem lembra.\n\nIsso não significa que testemunhas mintam, tampouco que seus relatos sejam inúteis. Significa que a forma de colher a lembrança interfere no conteúdo lembrado. Perguntas fechadas, que já trazem a resposta embutida, tendem a produzir confirmações; perguntas abertas, que deixam o depoente narrar com as próprias palavras, preservam melhor a lembrança original. Por isso, protocolos de entrevista investigativa recomendam que o policial fale pouco, interrompa menos ainda e evite, sobretudo, mostrar o que espera ouvir.", "enunciado": "Segundo o texto 2, a principal razão pela qual o relato de uma testemunha pode se afastar dos fatos é que", "opcoes": ["as perguntas abertas confundem o depoente e o levam a narrar fatos irrelevantes.", "a memória funciona como uma gravação que se apaga rapidamente com o passar do tempo.", "o depoente, por nervosismo, inventa detalhes para agradar ao policial.", "a memória é reconstruída a cada acesso e pode incorporar elementos externos, como sugestões do entrevistador.", "as testemunhas tendem a mentir deliberadamente para proteger conhecidos ou para evitar envolvimento com a investigação policial."], "gabarito": 3, "explicacao": "O texto afirma que a memória 'não arquiva fatos; reconstrói-os' e pode incorporar 'uma sugestão do entrevistador, uma notícia lida depois'. Diz também que isso não significa que testemunhas mintam."}, {"materia": "port", "texto_base": "O depoimento de uma testemunha costuma ser tratado como se fosse uma gravação: bastaria apertar o botão certo para que a cena retornasse intacta. A psicologia do testemunho mostra que não é assim. A memória não arquiva fatos; reconstrói-os a cada vez que é acessada, e cada reconstrução pode incorporar elementos que não estavam lá — uma sugestão do entrevistador, uma notícia lida depois, a própria expectativa de quem lembra.\n\nIsso não significa que testemunhas mintam, tampouco que seus relatos sejam inúteis. Significa que a forma de colher a lembrança interfere no conteúdo lembrado. Perguntas fechadas, que já trazem a resposta embutida, tendem a produzir confirmações; perguntas abertas, que deixam o depoente narrar com as próprias palavras, preservam melhor a lembrança original. Por isso, protocolos de entrevista investigativa recomendam que o policial fale pouco, interrompa menos ainda e evite, sobretudo, mostrar o que espera ouvir.", "enunciado": "Assinale a alternativa em que a reescrita do trecho “Isso não significa que testemunhas mintam, tampouco que seus relatos sejam inúteis” mantém o sentido e a correção gramatical.", "opcoes": ["Isso não significa que testemunhas mintam nem que seus relatos sejam inúteis.", "Isso significa que testemunhas não mintam, tampouco que seus relatos sejam úteis.", "Isso não significa que testemunhas mintam, inclusive que seus relatos sejam inúteis.", "Isso não significa que testemunhas mintam, porém que seus relatos sejam inúteis.", "Isso não significa que testemunhas mentem, tampouco que seus relatos são inúteis, conquanto sejam."], "gabarito": 0, "explicacao": "'Tampouco' equivale a 'nem' (adição negativa). 'Porém' traria oposição; 'inclusive' muda o sentido; as demais alteram o conteúdo."}, {"materia": "port", "texto_base": "O depoimento de uma testemunha costuma ser tratado como se fosse uma gravação: bastaria apertar o botão certo para que a cena retornasse intacta. A psicologia do testemunho mostra que não é assim. A memória não arquiva fatos; reconstrói-os a cada vez que é acessada, e cada reconstrução pode incorporar elementos que não estavam lá — uma sugestão do entrevistador, uma notícia lida depois, a própria expectativa de quem lembra.\n\nIsso não significa que testemunhas mintam, tampouco que seus relatos sejam inúteis. Significa que a forma de colher a lembrança interfere no conteúdo lembrado. Perguntas fechadas, que já trazem a resposta embutida, tendem a produzir confirmações; perguntas abertas, que deixam o depoente narrar com as próprias palavras, preservam melhor a lembrança original. Por isso, protocolos de entrevista investigativa recomendam que o policial fale pouco, interrompa menos ainda e evite, sobretudo, mostrar o que espera ouvir.", "enunciado": "No texto 2, a palavra “sobretudo”, em “evite, sobretudo, mostrar o que espera ouvir”, pode ser substituída, sem alteração de sentido, por", "opcoes": ["porventura.", "inclusive.", "principalmente.", "contudo.", "outrossim."], "gabarito": 2, "explicacao": "'Sobretudo' indica destaque, prioridade: 'principalmente', 'especialmente'. 'Contudo' é adversativo; 'outrossim' significa 'também'."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que o acento grave indicativo de crase está empregado corretamente.", "opcoes": ["O investigador começou à analisar as imagens das câmeras logo cedo.", "O delegado determinou que as testemunhas fossem ouvidas à medida que chegassem à delegacia.", "As diligências foram feitas de segunda à sexta-feira, sempre das 8h às 18h, conforme a escala do plantão.", "A equipe entregou o relatório à uma servidora do cartório.", "O suspeito ficou frente à frente com a vítima no reconhecimento."], "gabarito": 1, "explicacao": "'À medida que' (locução) e 'chegar à delegacia' (chegar a + a) levam crase. Não há crase antes de verbo (começou a), antes de artigo indefinido (a uma) nem em expressões com palavras repetidas (frente a frente). 'De segunda a sexta' fica sem crase, porque 'de' vem sem artigo."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que a regência verbal está de acordo com a norma-padrão.", "opcoes": ["O investigador assistiu o vídeo das câmeras várias vezes antes de concluir o relatório.", "O delegado informou aos familiares que o suspeito havia sido localizado.", "O escrivão esqueceu do horário marcado para a oitiva da vítima.", "Os agentes chegaram na residência do suspeito antes do amanhecer.", "A testemunha preferiu mais falar na delegacia do que em juízo."], "gabarito": 1, "explicacao": "'Informar algo a alguém' está correto. 'Preferir' não admite 'mais… do que' (prefere-se algo a outra coisa). 'Assistir' (ver) exige 'a': assistiu ao vídeo. 'Chegar' pede 'a': chegaram à residência. 'Esquecer' sem pronome não leva 'de': esqueceu o horário (ou esqueceu-se do horário)."}, {"materia": "rl", "texto_base": "", "enunciado": "Considere a afirmação: “Se o laudo confirma a lesão, então o inquérito é instaurado ou a vítima é ouvida novamente”. Uma afirmação logicamente equivalente é:", "opcoes": ["Se o laudo não confirma a lesão, então o inquérito não é instaurado e a vítima não é ouvida novamente.", "O laudo confirma a lesão e o inquérito não é instaurado ou a vítima não é ouvida novamente.", "O laudo não confirma a lesão e o inquérito é instaurado ou a vítima é ouvida novamente.", "Se o inquérito é instaurado ou a vítima é ouvida novamente, então o laudo confirma a lesão.", "Se o inquérito não é instaurado e a vítima não é ouvida novamente, então o laudo não confirma a lesão."], "gabarito": 4, "explicacao": "P → (Q ∨ R) equivale à contrapositiva ~(Q ∨ R) → ~P, isto é, (~Q ∧ ~R) → ~P (De Morgan). A alternativa com 'Se o laudo não confirma…' é a inversa, e a com 'Se o inquérito é instaurado ou…' é a recíproca: nenhuma das duas é equivalente."}, {"materia": "rl", "texto_base": "", "enunciado": "A negação de “Todos os investigadores do plantão concluíram o relatório e nenhum deles faltou à reunião” é:", "opcoes": ["Algum investigador do plantão não concluiu o relatório ou algum deles faltou à reunião.", "Nenhum investigador do plantão concluiu o relatório e todos faltaram à reunião.", "Se algum investigador concluiu o relatório, então algum deles faltou à reunião.", "Todos os investigadores do plantão não concluíram o relatório ou todos faltaram à reunião.", "Algum investigador do plantão não concluiu o relatório e algum deles faltou à reunião."], "gabarito": 0, "explicacao": "~(A ∧ B) = ~A ∨ ~B. A negação de 'Todos concluíram' é 'Algum não concluiu'; a de 'Nenhum faltou' é 'Algum faltou'. O conectivo 'e' vira 'ou'."}, {"materia": "rl", "texto_base": "", "enunciado": "Em uma operação, sabe-se que: (I) todo agente que usa colete participa da abordagem; (II) alguns agentes que participam da abordagem são do grupo tático; (III) nenhum agente do grupo tático dirige viatura. Com base nessas premissas, é necessariamente verdadeiro que", "opcoes": ["algum agente que participa da abordagem não dirige viatura.", "todo agente do grupo tático usa colete.", "algum agente que usa colete é do grupo tático.", "nenhum agente que usa colete dirige viatura.", "todo agente que participa da abordagem usa colete, já que a premissa I garante isso."], "gabarito": 0, "explicacao": "Por (II), existe ao menos um agente que participa da abordagem e é do grupo tático; por (III), ele não dirige viatura. Logo, algum agente que participa da abordagem não dirige viatura. As demais conclusões não decorrem necessariamente das premissas."}, {"materia": "rl", "texto_base": "", "enunciado": "Cinco investigadores — entre eles Ana e Bruno — serão dispostos em fila para uma foto oficial. Se Ana e Bruno devem ficar sempre juntos, lado a lado, o número de disposições possíveis é", "opcoes": ["72.", "96.", "120.", "24.", "48."], "gabarito": 4, "explicacao": "Trata-se o par Ana-Bruno como um bloco: 4 elementos permutados (4! = 24), vezes 2 ordens internas do bloco (2! = 2). Total: 48."}, {"materia": "rl", "texto_base": "", "enunciado": "Em uma urna há 5 envelopes com provas válidas e 3 com provas nulas. Retiram-se dois envelopes ao acaso, sem reposição. A probabilidade de que ambos contenham provas válidas é", "opcoes": ["15/56.", "3/8.", "25/64.", "5/14.", "5/8."], "gabarito": 3, "explicacao": "(5/8) × (4/7) = 20/56 = 5/14. Pela combinação, C(5,2)/C(8,2) = 10/28 = 5/14. 25/64 seria o resultado com reposição."}, {"materia": "rl", "texto_base": "", "enunciado": "Três suspeitos — Abel, Beto e Caio — prestaram depoimento. Abel disse: “Beto mente”. Beto disse: “Caio mente”. Caio disse: “Abel e Beto mentem”. Sabendo que cada um ou sempre diz a verdade ou sempre mente, conclui-se que", "opcoes": ["apenas Beto diz a verdade.", "Abel e Caio dizem a verdade.", "apenas Caio diz a verdade.", "os três mentem.", "apenas Abel diz a verdade."], "gabarito": 0, "explicacao": "Se Caio dissesse a verdade, Abel e Beto mentiriam; mas, se Beto mente, Caio diz a verdade (ok) e, se Abel mente, Beto diz a verdade — contradição. Logo, Caio mente; então Beto (que disse 'Caio mente') diz a verdade e Abel (que disse 'Beto mente') mente. Confere: Caio disse 'Abel e Beto mentem', o que é falso, pois Beto diz a verdade."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma sequência de códigos segue o padrão: 3, 7, 15, 31, 63, … O oitavo termo dessa sequência é", "opcoes": ["1023.", "255.", "127.", "511.", "509."], "gabarito": 3, "explicacao": "Cada termo é o dobro do anterior mais 1 (aₙ = 2ⁿ⁺¹ − 1): 3, 7, 15, 31, 63, 127, 255, 511. O 8º termo é 511."}, {"materia": "inf", "texto_base": "", "enunciado": "Um investigador recebeu um e-mail aparentemente enviado pelo setor de TI da instituição, pedindo que ele clicasse em um link para “revalidar a senha” em até 2 horas, sob pena de bloqueio. Esse cenário caracteriza principalmente", "opcoes": ["spam comercial sem finalidade maliciosa.", "ataque de negação de serviço (DDoS), que sobrecarrega o servidor de e-mail.", "keylogger instalado por vulnerabilidade de hardware.", "ransomware, que criptografa arquivos e exige resgate.", "phishing, técnica de engenharia social para capturar credenciais."], "gabarito": 4, "explicacao": "Phishing usa mensagens falsas, com urgência e aparência legítima, para induzir a vítima a entregar senhas ou clicar em links maliciosos."}, {"materia": "inf", "texto_base": "", "enunciado": "Em uma planilha do Excel, o intervalo A1:A5 contém os bairros “Centro”, “Barra”, “Centro”, “Pituba” e “Centro”, e o intervalo B1:B5 contém, respectivamente, as ocorrências 4, 7, 2, 5 e 3. A fórmula =SOMASE(A1:A5;\"Centro\";B1:B5) retorna", "opcoes": ["3.", "9.", "12.", "4.", "21."], "gabarito": 1, "explicacao": "SOMASE soma os valores de B correspondentes às linhas em que A é 'Centro': 4 + 2 + 3 = 9. CONT.SE retornaria 3 (quantidade de linhas)."}, {"materia": "inf", "texto_base": "", "enunciado": "Sobre cópias de segurança (backup), assinale a alternativa correta.", "opcoes": ["O backup incremental, por copiar tudo a cada execução, é o que ocupa mais espaço.", "O backup incremental copia apenas os arquivos alterados desde o último backup de qualquer tipo, o que torna a restauração dependente de toda a cadeia de incrementais.", "O backup completo dispensa marcação de arquivos e, por isso, é o mais rápido de executar.", "A restauração a partir de backups diferenciais exige o último backup completo e todos os diferenciais feitos desde então, na ordem em que foram gerados.", "O backup diferencial copia apenas os arquivos alterados desde o último backup diferencial."], "gabarito": 1, "explicacao": "Incremental: alterados desde o último backup (completo ou incremental); a restauração precisa do completo + todos os incrementais. Diferencial: alterados desde o último completo; a restauração precisa do completo + o último diferencial."}, {"materia": "inf", "texto_base": "", "enunciado": "Em relação aos protocolos de internet, é correto afirmar que", "opcoes": ["o HTTPS combina o HTTP com criptografia TLS, protegendo os dados trafegados entre o navegador e o servidor.", "o DNS criptografa as senhas digitadas em formulários web.", "o IMAP apaga as mensagens do servidor assim que elas são baixadas para o computador.", "o FTP é o protocolo padrão para navegação segura em páginas web.", "o SMTP é o protocolo usado para receber e-mails no computador do usuário, enquanto o POP3 é usado para enviá-los ao servidor."], "gabarito": 0, "explicacao": "HTTPS = HTTP sobre TLS. SMTP envia e-mails; POP3 e IMAP recebem. O DNS traduz nomes em endereços IP. O IMAP mantém as mensagens sincronizadas no servidor."}, {"materia": "inf", "texto_base": "", "enunciado": "No Windows 10/11, ao selecionar um arquivo no Explorador de Arquivos e pressionar Shift + Delete, o arquivo", "opcoes": ["tem seus atributos alterados para oculto.", "é excluído permanentemente, sem ir para a Lixeira (após confirmação).", "é renomeado.", "é copiado para a área de transferência.", "é movido para a Lixeira, podendo ser restaurado depois pelo próprio usuário."], "gabarito": 1, "explicacao": "Shift + Delete exclui sem passar pela Lixeira, normalmente após uma caixa de confirmação. Delete sozinho envia para a Lixeira."}, {"materia": "inf", "texto_base": "", "enunciado": "Sobre a autenticação em dois fatores (2FA), assinale a alternativa correta.", "opcoes": ["Consiste em exigir duas senhas diferentes digitadas em sequência.", "Só pode ser usada em redes corporativas com servidor próprio.", "Combina dois elementos de categorias diferentes, como algo que o usuário sabe (senha) e algo que ele possui (código no celular).", "É uma técnica de criptografia que duplica o tamanho da chave.", "Dispensa o uso de senha, pois a biometria, sozinha, já constitui dois fatores de autenticação: o que o usuário é e o que ele possui."], "gabarito": 2, "explicacao": "2FA exige dois fatores de categorias distintas: conhecimento (senha), posse (token, celular) ou inerência (biometria). Duas senhas são o mesmo fator."}, {"materia": "inf", "texto_base": "", "enunciado": "No Microsoft Word, o recurso que permite registrar as alterações feitas por diferentes revisores em um documento, possibilitando aceitá-las ou rejeitá-las depois, é", "opcoes": ["Proteger Documento com senha, na guia Arquivo.", "Controlar Alterações, na guia Revisão.", "Quebras de Seção, na guia Layout.", "Mala Direta, na guia Correspondências.", "Pincel de Formatação, na guia Página Inicial."], "gabarito": 1, "explicacao": "O Controlar Alterações (guia Revisão) marca inserções, exclusões e formatações, que depois podem ser aceitas ou rejeitadas."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "Em maio de 2025, o conclave elegeu o novo papa da Igreja Católica, sucessor de Francisco. O escolhido, primeiro pontífice nascido nos Estados Unidos, adotou o nome de", "opcoes": ["João XXIV.", "Paulo VII.", "Leão XIV.", "Pio XIII.", "Bento XVII."], "gabarito": 2, "explicacao": "O cardeal Robert Francis Prevost foi eleito em 8 de maio de 2025 e adotou o nome de Leão XIV."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "Em 2025, o Banco Central lançou uma nova funcionalidade do Pix voltada a pagamentos recorrentes, como contas de consumo e mensalidades, autorizados uma única vez pelo pagador. Essa funcionalidade é o", "opcoes": ["Pix Troco.", "Pix Saque Digital.", "Pix Automático.", "Pix Parcelado.", "Pix Garantido."], "gabarito": 2, "explicacao": "O Pix Automático começou a funcionar em junho de 2025 e permite débitos recorrentes autorizados previamente pelo pagador."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "Em 2025, o Congresso aprovou e o presidente sancionou a lei que ampliou a isenção do Imposto de Renda da Pessoa Física, com vigência a partir de 2026. A nova regra isenta quem recebe até", "opcoes": ["R$ 10.000,00 por mês, sem nenhum tipo de compensação para as rendas mais altas.", "R$ 7.500,00 por mês, apenas para aposentados.", "R$ 2.824,00 por mês, sem alteração em relação a 2024.", "R$ 5.000,00 por mês, com desconto parcial para rendas um pouco acima desse valor.", "R$ 3.036,00 por mês, equivalente a dois salários mínimos."], "gabarito": 3, "explicacao": "A lei sancionada em novembro de 2025 isentou do IR quem ganha até R$ 5 mil por mês a partir de 2026, com redução gradual para rendas até cerca de R$ 7.350, compensada por tributação mínima sobre altas rendas."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "Em 2025, os Estados Unidos anunciaram a aplicação de uma tarifa adicional sobre importações de produtos brasileiros, o que gerou reação do governo federal e debate sobre a Lei de Reciprocidade Econômica. A alíquota adicional anunciada foi de", "opcoes": ["100%.", "10%.", "25%.", "5%.", "50%."], "gabarito": 4, "explicacao": "Em julho de 2025, o governo norte-americano anunciou tarifa de 50% sobre produtos brasileiros, com lista de exceções, em vigor a partir de agosto de 2025."}, {"materia": "igual", "texto_base": "", "enunciado": "Sobre a Lei 14.994/2024 (pacote antifeminicídio), assinale a alternativa correta.", "opcoes": ["Retirou o feminicídio do rol de crimes hediondos, para permitir a progressão mais rápida.", "Passou a exigir representação da vítima para o crime de lesão corporal no contexto doméstico.", "Transformou o feminicídio em crime autônomo (art. 121-A do Código Penal), com pena de reclusão de 20 a 40 anos.", "Manteve o feminicídio como qualificadora do homicídio (art. 121, § 2º, VI), apenas aumentando a pena mínima para 15 anos.", "Revogou a Lei Maria da Penha, incorporando seus dispositivos ao Código Penal."], "gabarito": 2, "explicacao": "A Lei 14.994/2024 criou o art. 121-A do CP (feminicídio como crime autônomo), com reclusão de 20 a 40 anos, e manteve o crime como hediondo."}, {"materia": "igual", "texto_base": "", "enunciado": "Segundo a Lei 11.340/2006 (Lei Maria da Penha), as medidas protetivas de urgência", "opcoes": ["dependem sempre de audiência prévia com a presença do agressor, para garantir o contraditório, e só podem ser concedidas depois do registro do boletim de ocorrência.", "podem ser concedidas independentemente da tipificação penal da violência, do ajuizamento de ação penal ou cível, da existência de inquérito ou do registro de boletim de ocorrência.", "perdem a validade automaticamente após 30 dias, sem possibilidade de prorrogação.", "só podem ser concedidas depois do recebimento da denúncia pelo juiz.", "só podem ser requeridas pelo Ministério Público."], "gabarito": 1, "explicacao": "O art. 19, § 5º, incluído pela Lei 14.550/2023, prevê a concessão das medidas independentemente de tipificação penal, ação, inquérito ou BO. A ofendida pode requerê-las diretamente, e o juiz pode concedê-las de imediato."}, {"materia": "igual", "texto_base": "", "enunciado": "De acordo com a Lei 7.716/1989, com a redação dada pela Lei 14.532/2023, o crime de injúria racial (art. 2º-A)", "opcoes": ["é punido com detenção de 1 a 3 meses.", "tem a pena aumentada quando praticado por funcionário público no exercício de suas funções ou a pretexto de exercê-las.", "admite fiança e prescreve em 2 anos.", "é de ação penal privada, procedendo-se mediante queixa da vítima no prazo decadencial de 6 meses, contado do conhecimento da autoria.", "só se configura se praticado em local público."], "gabarito": 1, "explicacao": "O art. 20-B da Lei 7.716/1989 aumenta a pena dos crimes dos arts. 2º-A e 20 quando praticados por funcionário público no exercício das funções ou a pretexto de exercê-las. A injúria racial é imprescritível e inafiançável (equiparada ao racismo), com reclusão de 2 a 5 anos."}, {"materia": "igual", "texto_base": "", "enunciado": "Sobre o Estatuto da Igualdade Racial (Lei 12.288/2010), assinale a alternativa correta.", "opcoes": ["Define desigualdade racial como toda situação injustificada de diferenciação de acesso e fruição de bens, serviços e oportunidades, nas esferas pública e privada, em virtude de raça, cor, descendência ou origem nacional ou étnica.", "Considera população negra apenas as pessoas que se autodeclaram pretas, excluídas as pardas, que são contabilizadas separadamente para fins de políticas públicas e de ações afirmativas no mercado de trabalho e na educação.", "Tipifica o crime de racismo e fixa suas penas.", "Proíbe a adoção de ações afirmativas, por considerá-las discriminação reversa.", "Aplica-se apenas às relações de trabalho no setor público federal."], "gabarito": 0, "explicacao": "Art. 1º, parágrafo único, II, da Lei 12.288/2010. O Estatuto prevê ações afirmativas, define população negra como pretos e pardos, e os crimes de racismo estão na Lei 7.716/1989."}, {"materia": "ml", "texto_base": "", "enunciado": "Ao examinar um cadáver, o perito observa ferida de entrada de projétil com orla de escoriação, zona de tatuagem e zona de esfumaçamento ao redor. Esses achados indicam, em regra, disparo", "opcoes": ["a longa distância, fora do alcance dos resíduos de pólvora.", "encostado, com a boca do cano apoiada firmemente na pele, o que espalha os resíduos ao redor do orifício.", "post mortem, por ausência de reação vital.", "a curta distância, dentro do alcance dos resíduos da combustão da pólvora.", "com projétil que atravessou anteparo antes de atingir a vítima."], "gabarito": 3, "explicacao": "Tatuagem (grãos de pólvora incrustados) e esfumaçamento (fuligem) aparecem nos disparos a curta distância. No disparo encostado há câmara de mina (sinal de Hoffmann); a longa distância só há orla de escoriação e enxugo."}, {"materia": "ml", "texto_base": "", "enunciado": "Em relação aos fenômenos cadavéricos, assinale a alternativa correta.", "opcoes": ["A saponificação ocorre preferencialmente em ambientes secos e muito ventilados.", "Os livores de hipóstase fixam-se, em geral, após cerca de 12 horas, passando a não mudar de posição com a movimentação do corpo.", "O resfriamento cadavérico é um fenômeno transformativo destrutivo.", "A rigidez cadavérica começa pelos membros inferiores e progride em direção à cabeça (sentido podálico-cefálico).", "A mancha verde abdominal, primeiro sinal da putrefação, surge normalmente na fossa ilíaca esquerda, por causa do cólon descendente."], "gabarito": 1, "explicacao": "Os livores se fixam por volta de 8 a 12 horas. A rigidez segue a lei de Nysten (crânio-caudal). A mancha verde surge na fossa ilíaca direita. O resfriamento é fenômeno abiótico consecutivo. A saponificação (adipocera) exige umidade e pouca aeração."}, {"materia": "ml", "texto_base": "", "enunciado": "Uma vítima apresenta, no pescoço, sulco único, horizontal, de profundidade uniforme, contínuo ao redor de todo o pescoço e situado abaixo da cartilagem tireoide. Esse padrão é mais compatível com", "opcoes": ["esganadura.", "afogamento.", "estrangulamento por laço.", "sufocação direta.", "enforcamento típico com nó."], "gabarito": 2, "explicacao": "No estrangulamento por laço, o sulco é geralmente horizontal, contínuo e de profundidade uniforme, muitas vezes abaixo da tireoide. No enforcamento, o sulco é oblíquo e ascendente, interrompido no ponto do nó. A esganadura é feita com as mãos e não deixa sulco."}, {"materia": "ml", "texto_base": "", "enunciado": "Na classificação das lesões corporais quanto ao resultado, constitui lesão corporal gravíssima (art. 129, § 2º, do Código Penal)", "opcoes": ["a deformidade permanente.", "a aceleração de parto.", "a debilidade permanente de membro, sentido ou função.", "a incapacidade para as ocupações habituais por mais de 30 dias.", "o perigo de vida."], "gabarito": 0, "explicacao": "O § 2º (gravíssima) inclui incapacidade permanente para o trabalho, enfermidade incurável, perda ou inutilização de membro, sentido ou função, deformidade permanente e aborto. Os demais itens estão no § 1º (grave)."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Um servidor público civil do Estado da Bahia praticou infração punível com suspensão. A Administração tomou conhecimento do fato em março de 2023, mas só instaurou o processo disciplinar em maio de 2025. De acordo com a Lei Estadual 6.677/1994,", "opcoes": ["a ação disciplinar está prescrita, pois a prescrição para a suspensão é de 2 anos, contados da data em que o fato se tornou conhecido.", "não há prescrição para infrações puníveis com suspensão.", "a ação disciplinar não está prescrita, pois o prazo para a suspensão é de 5 anos, contados da data em que o fato se tornou conhecido.", "a prescrição só começa a correr a partir da instauração do processo disciplinar.", "a ação disciplinar está prescrita, pois o prazo para qualquer penalidade é de 180 dias."], "gabarito": 0, "explicacao": "Art. 203: prescreve em 5 anos (demissão e cassação), 2 anos (suspensão) e 180 dias (advertência). O prazo começa na data em que o fato se tornou conhecido (§ 1º). De março de 2023 a maio de 2025 passaram mais de 2 anos."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Nos termos da Lei Estadual 6.677/1994, a penalidade de suspensão", "opcoes": ["pode chegar a 180 dias, e seu registro é cancelado após 2 anos de efetivo exercício, se o servidor não cometer nova infração.", "pode ser convertida em multa de 50% da remuneração, a pedido do servidor.", "não pode exceder 90 dias, e seu registro é cancelado após 4 anos de efetivo exercício, se o servidor não praticar nova infração.", "tem o registro cancelado com efeitos retroativos após 5 anos.", "não pode exceder 30 dias, e seu registro nunca é cancelado."], "gabarito": 2, "explicacao": "Art. 190: a suspensão não pode exceder 90 dias. Art. 191: os registros de advertência e suspensão são cancelados após 2 e 4 anos de efetivo exercício, respectivamente, sem nova infração, e o cancelamento não tem efeitos retroativos."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Segundo a Lei Estadual 6.677/1994, o processo administrativo disciplinar deve ser concluído no prazo de", "opcoes": ["30 dias úteis, improrrogáveis.", "90 dias, sem possibilidade de prorrogação.", "120 dias, prorrogáveis por mais 60 dias, a critério da comissão processante.", "60 dias, admitida prorrogação por igual prazo em circunstâncias excepcionais.", "180 dias, contados da citação do acusado."], "gabarito": 3, "explicacao": "Art. 216: o processo deve ser iniciado em até 5 dias da instauração e concluído em até 60 dias, prorrogáveis por igual prazo em circunstâncias excepcionais. Os 30 dias úteis valem para a sindicância (art. 205, § 3º)."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Determinado servidor do Estado da Bahia, aposentado por invalidez, teve declarados insubsistentes, por junta médica oficial, os motivos da aposentadoria e retornou à atividade. De acordo com a Lei Estadual 6.677/1994, esse retorno denomina-se", "opcoes": ["recondução.", "reintegração.", "readaptação.", "aproveitamento.", "reversão."], "gabarito": 4, "explicacao": "Art. 34: reversão é o retorno do aposentado por invalidez quando insubsistentes os motivos da aposentadoria. Reintegração é o retorno do demitido (art. 41); aproveitamento, do servidor em disponibilidade (art. 38); readaptação, novas atribuições por limitação (art. 43)."}, {"materia": "pen", "texto_base": "", "enunciado": "Túlio, querendo matar Pedro, disparou contra ele, mas errou o alvo e atingiu Lucas, que estava ao lado, matando-o. Pedro não foi atingido. Nessa situação, Túlio responde", "opcoes": ["por tentativa de homicídio contra Pedro, sem responsabilidade pela morte de Lucas.", "por tentativa de homicídio contra Pedro em concurso formal com homicídio culposo contra Lucas, somando-se as penas dos dois crimes.", "apenas por homicídio culposo contra Lucas, porque não quis matá-lo.", "por homicídio doloso consumado, considerando-se as qualidades de Pedro, e não as de Lucas (aberratio ictus com resultado único).", "por homicídio doloso consumado, considerando-se as qualidades de Lucas."], "gabarito": 3, "explicacao": "Erro na execução (art. 73 do CP): com resultado único, o agente responde como se tivesse atingido a vítima visada, considerando-se as qualidades dela (art. 20, § 3º). Se atingisse também Pedro, haveria concurso formal (art. 73, parte final)."}, {"materia": "pen", "texto_base": "", "enunciado": "Marcos invadiu uma residência para furtar, mas, ao ouvir um barulho, desistiu voluntariamente de prosseguir e saiu sem levar nada, embora pudesse ter continuado. Nesse caso, Marcos", "opcoes": ["responde por tentativa de furto qualificado, com redução de 1/3 a 2/3, pois a execução já havia começado.", "não responde por crime algum, pois a desistência apaga todos os atos anteriores.", "responde apenas pelos atos já praticados, como a violação de domicílio, em razão da desistência voluntária.", "é beneficiado pelo arrependimento posterior, com redução de pena.", "responde por furto consumado, pois ingressou no imóvel."], "gabarito": 2, "explicacao": "Desistência voluntária (art. 15 do CP): o agente que, podendo prosseguir, desiste voluntariamente, só responde pelos atos já praticados. A invasão configura violação de domicílio (art. 150)."}, {"materia": "pen", "texto_base": "", "enunciado": "Sobre o crime de roubo, assinale a alternativa correta de acordo com o entendimento dos tribunais superiores.", "opcoes": ["Admite o princípio da insignificância quando o valor subtraído for inferior a 10% do salário mínimo e a vítima não sofrer lesão corporal grave.", "Exige a posse mansa e pacífica do bem para se consumar.", "A arma de brinquedo autoriza o aumento de pena previsto para o emprego de arma de fogo.", "Subtração de vários bens de vítimas diferentes, com uma só ameaça, configura crime único.", "Consuma-se com a inversão da posse do bem mediante violência ou grave ameaça, ainda que por breve tempo e com perseguição imediata (Súmula 582 do STJ)."], "gabarito": 4, "explicacao": "Súmula 582 do STJ: teoria da amotio. O STF e o STJ não admitem insignificância no roubo. O simulacro não aplica a majorante de arma de fogo. Roubo com uma ameaça contra vítimas diferentes, atingindo patrimônios distintos, é concurso formal."}, {"materia": "pen", "texto_base": "", "enunciado": "Valéria, funcionária pública, exigiu de um empresário, para si, R$ 5.000,00 para não lavrar auto de infração que era devido. O empresário não pagou e denunciou o fato. Valéria cometeu", "opcoes": ["prevaricação, pois deixou de praticar ato de ofício para satisfazer interesse pessoal.", "tentativa de concussão, pois a vantagem não foi recebida.", "concussão consumada, pois o crime é formal e se consuma com a exigência.", "extorsão, pois houve constrangimento para obter vantagem.", "corrupção passiva consumada, pois houve solicitação de vantagem."], "gabarito": 2, "explicacao": "Concussão (art. 316 do CP): exigir vantagem indevida em razão da função. É crime formal: consuma-se com a exigência; o recebimento é mero exaurimento. 'Exigir' diferencia a concussão da corrupção passiva ('solicitar, receber, aceitar promessa')."}, {"materia": "pen", "texto_base": "", "enunciado": "Sobre a legítima defesa, assinale a alternativa correta.", "opcoes": ["Exige que a agressão seja atual, não se admitindo reação contra agressão iminente.", "É incompatível com o excesso culposo, que sempre exclui a excludente e faz o agente responder pelo crime doloso, ainda que a agressão inicial tenha sido injusta.", "Considera-se em legítima defesa o agente de segurança pública que repele agressão ou risco de agressão a vítima mantida refém durante a prática de crimes.", "Exige que o agredido tente fugir antes de reagir (commodus discessus obrigatório).", "Só pode ser exercida para defender direito próprio, nunca de terceiros."], "gabarito": 2, "explicacao": "O parágrafo único do art. 25 do CP, incluído pelo Pacote Anticrime, trata do agente de segurança pública que repele agressão a refém. A agressão pode ser atual ou iminente; vale para direito próprio ou alheio; o excesso doloso ou culposo é punível (art. 23, parágrafo único); não há dever de fuga."}, {"materia": "pen", "texto_base": "", "enunciado": "André, maior de idade, praticou furto simples contra seu irmão Bruno, de 45 anos, com quem não coabita. Sobre a ação penal, é correto afirmar que", "opcoes": ["o crime é de ação penal privada.", "André responde com pena aumentada de metade, pelo parentesco.", "o crime é de ação penal pública incondicionada.", "o crime é de ação penal pública condicionada à representação de Bruno.", "André é isento de pena, por se tratar de crime contra irmão, nos termos do art. 181 do Código Penal."], "gabarito": 3, "explicacao": "Art. 182, II, do CP: somente se procede mediante representação se o crime é cometido em prejuízo de irmão, legítimo ou ilegítimo. A isenção de pena (art. 181) alcança cônjuge na constância da sociedade conjugal e ascendente ou descendente; não alcança irmão. Não incide a exceção do art. 183, III, pois Bruno tem menos de 60 anos."}, {"materia": "pen", "texto_base": "", "enunciado": "De acordo com o Código Penal, assinale a alternativa correta sobre o crime continuado.", "opcoes": ["Não é admitido em crimes contra a vida.", "Nos crimes dolosos contra vítimas diferentes, cometidos com violência ou grave ameaça, o juiz pode aumentar a pena de um só dos crimes até o triplo.", "O aumento é fixo de 1/6, independentemente do número de infrações.", "Exige que os crimes sejam idênticos, isto é, previstos no mesmo tipo penal, não bastando que sejam da mesma espécie nem que haja semelhança de tempo e lugar.", "Implica sempre a soma das penas de todos os crimes praticados."], "gabarito": 1, "explicacao": "Art. 71, parágrafo único, do CP: crime continuado específico, com aumento até o triplo. Bastam crimes da mesma espécie; aplica-se a pena de um só, aumentada de 1/6 a 2/3 no caso comum; a Súmula 605 do STF, que vedava a continuidade nos crimes contra a vida, está superada pela reforma de 1984."}, {"materia": "pen", "texto_base": "", "enunciado": "Rui furtou o celular de Carla, sem violência ou grave ameaça. Antes do recebimento da denúncia, por ato voluntário, devolveu o aparelho e ressarciu os prejuízos. Nessa situação,", "opcoes": ["a reparação serve apenas como atenuante genérica, sem redução de 1/3 a 2/3.", "extingue-se a punibilidade, pois o dano foi integralmente reparado antes da denúncia.", "há desistência voluntária, e Rui não responde por furto.", "incide o arrependimento posterior, com redução da pena de 1/3 a 2/3.", "aplica-se o arrependimento eficaz, e Rui responde só pelos atos já praticados."], "gabarito": 3, "explicacao": "Art. 16 do CP: nos crimes sem violência ou grave ameaça, reparado o dano ou restituída a coisa, por ato voluntário, até o recebimento da denúncia, a pena é reduzida de 1/3 a 2/3. Arrependimento eficaz e desistência voluntária ocorrem antes da consumação (art. 15)."}, {"materia": "pen", "texto_base": "", "enunciado": "Quanto ao crime de associação criminosa (art. 288 do Código Penal), é correto afirmar que", "opcoes": ["só se consuma quando o grupo pratica o primeiro crime planejado.", "exige a associação de no mínimo 4 pessoas, com estrutura ordenada e divisão de tarefas, para a prática de infrações com pena máxima superior a 4 anos.", "exige a associação de 3 ou mais pessoas, para o fim específico de cometer crimes, e se consuma independentemente da prática de qualquer crime.", "pode ser formado para a prática de contravenções penais.", "tem a pena aumentada até o dobro se houver participação de criança, mas não de adolescente."], "gabarito": 2, "explicacao": "Art. 288: associarem-se 3 ou mais pessoas para o fim específico de cometer crimes. É crime formal e permanente. A pena aumenta até a metade se armada ou com participação de criança ou adolescente. Quatro ou mais pessoas e estrutura ordenada caracterizam organização criminosa (Lei 12.850/2013)."}, {"materia": "pen", "texto_base": "", "enunciado": "Sobre a extinção da punibilidade, assinale a alternativa correta.", "opcoes": ["O perdão judicial é causa de extinção da punibilidade cabível em qualquer crime, a critério do juiz.", "A morte do agente extingue a punibilidade apenas se ocorrer antes do trânsito em julgado.", "A prescrição é contada em dobro para quem, ao tempo do crime, era maior de 70 anos, como forma de compensar a menor expectativa de vida do réu.", "Nos crimes conexos, a extinção da punibilidade de um deles não impede, quanto aos outros, a agravação da pena resultante da conexão.", "A renúncia ao direito de queixa, em relação a um dos autores do crime, não se estende aos demais."], "gabarito": 3, "explicacao": "Art. 108 do CP. Os prazos de prescrição são reduzidos de metade para menores de 21 ao tempo do crime ou maiores de 70 na sentença (art. 115). O perdão judicial só cabe nos casos previstos em lei. A renúncia se estende a todos (art. 49 do CPP). A morte extingue a punibilidade a qualquer tempo."}, {"materia": "ppen", "texto_base": "", "enunciado": "Policiais recebem informação de que um assalto a banco ocorrerá na sexta-feira, ficam de prontidão dentro da agência e prendem os autores no momento em que anunciam o roubo, sem ter induzido os criminosos. Essa prisão é", "opcoes": ["ilegal, por se tratar de flagrante preparado, nos termos da Súmula 145 do STF.", "ilegal, porque a polícia tinha o dever de impedir o início da execução.", "ilegal, por se tratar de flagrante forjado.", "válida apenas se houver prévia autorização judicial para a ação controlada.", "válida, tratando-se de flagrante esperado."], "gabarito": 4, "explicacao": "No flagrante esperado, a polícia apenas aguarda o crime, sem induzir o agente, e a prisão é válida. O flagrante preparado (Súmula 145 do STF) exige indução por agente provocador e impossibilidade de consumação. O forjado envolve provas plantadas."}, {"materia": "ppen", "texto_base": "", "enunciado": "De acordo com a Lei 12.830/2013, que trata da investigação criminal conduzida pelo delegado de polícia, o indiciamento", "opcoes": ["é ato privativo do delegado de polícia, feito por ato fundamentado, mediante análise técnico-jurídica do fato, que deve indicar a autoria, a materialidade e suas circunstâncias.", "é ato discricionário que dispensa fundamentação, pois o inquérito é inquisitivo.", "pode ser determinado pelo juiz, de ofício, quando entender que há indícios suficientes.", "pode ser requisitado pelo Ministério Público, ficando o delegado obrigado a realizá-lo, já que o MP é o titular da ação penal e pode exercer o controle externo da atividade policial sobre o inquérito.", "só pode ocorrer depois do interrogatório judicial do investigado."], "gabarito": 0, "explicacao": "Art. 2º, § 6º, da Lei 12.830/2013. O STF e o STJ entendem que o juiz não pode determinar o indiciamento e que o MP não pode requisitá-lo, por ser ato privativo da autoridade policial."}, {"materia": "ppen", "texto_base": "", "enunciado": "De acordo com o Código de Processo Penal, após as alterações do Pacote Anticrime, a autoridade policial que receber o preso em flagrante deve", "opcoes": ["conceder liberdade provisória com fiança em qualquer crime cuja pena máxima seja de até 8 anos.", "realizar a audiência de custódia em até 48 horas na própria delegacia, com a presença do Ministério Público e da defesa, decidindo sobre a manutenção da prisão em flagrante.", "encaminhar o auto à Defensoria Pública apenas se o preso tiver advogado constituído.", "aguardar o término do inquérito para comunicar a prisão ao juiz.", "comunicar imediatamente a prisão ao juiz competente, ao Ministério Público e à família do preso ou à pessoa por ele indicada, e encaminhar o auto ao juiz em até 24 horas."], "gabarito": 4, "explicacao": "Arts. 306 e § 1º do CPP: comunicação imediata ao juiz, ao MP e à família; auto ao juiz em até 24 horas (e cópia à Defensoria, se não houver advogado). A audiência de custódia é feita pelo juiz (art. 310). O delegado só arbitra fiança se a pena máxima não passar de 4 anos (art. 322)."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a cadeia de custódia, assinale a alternativa correta.", "opcoes": ["Todos os vestígios coletados devem ser tratados como de natureza criminal, e o agente público que reconhecer um elemento como de potencial interesse para a perícia fica responsável por sua preservação.", "Inicia-se apenas com a chegada do vestígio ao instituto de criminalística, quando o perito registra o material recebido, e por isso as etapas anteriores, como a coleta no local do crime, não integram a cadeia de custódia.", "Pode ser rompida por qualquer pessoa que tenha interesse no processo, desde que registre o fato.", "Admite que o perito descarte o vestígio logo após a perícia, independentemente de autorização.", "Dispensa o lacre quando o vestígio for de pequeno porte."], "gabarito": 0, "explicacao": "Art. 158-A, §§ 2º e 3º, e art. 158-B do CPP: a cadeia começa com a preservação do local ou com o reconhecimento do vestígio. Os vestígios devem ser lacrados. O rompimento do lacre só por perito ou pessoa autorizada, com registro (art. 158-D, § 3º)."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a prisão temporária (Lei 7.960/1989), assinale a alternativa correta.", "opcoes": ["Nos crimes hediondos e equiparados, o prazo é de 30 dias, prorrogável por igual período em caso de extrema e comprovada necessidade.", "Tem prazo de 10 dias, prorrogável uma única vez por igual período, em qualquer crime, inclusive nos hediondos e nos equiparados a hediondos.", "Pode ser decretada pelo delegado de polícia, em caso de urgência.", "Pode ser decretada de ofício pelo juiz durante a ação penal.", "Cabe em qualquer crime punido com reclusão, independentemente de rol legal."], "gabarito": 0, "explicacao": "Lei 8.072/1990, art. 2º, § 4º: 30 + 30 dias nos hediondos. Na regra geral, 5 + 5 dias (Lei 7.960/1989). Só cabe na investigação, decretada pelo juiz mediante representação do delegado ou requerimento do MP, e nos crimes do rol do art. 1º, III."}, {"materia": "ppen", "texto_base": "", "enunciado": "Em relação ao reconhecimento de pessoas, segundo o entendimento atual do STJ, é correto afirmar que", "opcoes": ["o reconhecimento fotográfico por álbum de suspeitos dispensa qualquer formalidade e basta para a condenação.", "é proibido o reconhecimento pessoal em juízo se já houve reconhecimento na fase policial.", "o procedimento do art. 226 do CPP é garantia mínima do suspeito, e o reconhecimento feito sem observá-lo não pode, sozinho, fundamentar a condenação.", "o art. 226 do CPP traz mera recomendação ao delegado e ao juiz, e seu descumprimento nunca gera nulidade, desde que a vítima confirme o reconhecimento em juízo.", "o reconhecimento feito na delegacia vincula o juiz, que não pode afastá-lo."], "gabarito": 2, "explicacao": "Desde o HC 598.886/SC (2020), o STJ entende que o art. 226 é garantia mínima, e o reconhecimento irregular não serve, isoladamente, para condenar. O entendimento foi reforçado em julgados posteriores."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a busca domiciliar sem mandado, assinale a alternativa correta.", "opcoes": ["A simples fuga do suspeito ao avistar a viatura autoriza, por si só, o ingresso em qualquer imóvel no qual ele entre, a qualquer hora do dia ou da noite, independentemente de outros elementos.", "É lícita em caso de flagrante delito, desde que amparada em fundadas razões, justificadas a posteriori, que indiquem situação de flagrante dentro da casa.", "É proibida à noite, mesmo em flagrante delito.", "É lícita sempre que houver denúncia anônima sobre tráfico de drogas no local.", "É lícita durante o dia, mesmo sem flagrante, se o delegado autorizar por escrito."], "gabarito": 1, "explicacao": "Art. 5º, XI, da CF e Tema 280 do STF (RE 603.616): o ingresso forçado sem mandado exige fundadas razões, justificadas depois, de que há flagrante no interior. O STJ entende que denúncia anônima isolada e fuga, por si sós, não bastam. Em flagrante, cabe a qualquer hora."}, {"materia": "ppen", "texto_base": "", "enunciado": "O Pacote Anticrime incluiu no CPP o acordo de não persecução penal (ANPP). Sobre ele, assinale a alternativa correta.", "opcoes": ["Pode ser celebrado diretamente entre o delegado de polícia e o investigado, ainda na fase de inquérito, desde que haja confissão formal e circunstanciada e a reparação do dano à vítima.", "Pode ser proposto pelo Ministério Público quando o investigado confessa formal e circunstancialmente infração sem violência ou grave ameaça, com pena mínima inferior a 4 anos.", "Cabe nos crimes praticados no âmbito de violência doméstica contra a mulher.", "Exige que a pena máxima do crime seja inferior a 2 anos.", "Dispensa homologação judicial."], "gabarito": 1, "explicacao": "Art. 28-A do CPP. É proposto pelo MP, homologado pelo juiz em audiência (§ 4º). Não cabe em violência doméstica ou familiar ou contra a mulher por razões da condição do sexo feminino (§ 2º, IV)."}, {"materia": "ppen", "texto_base": "", "enunciado": "De acordo com o Código de Processo Penal, a prisão preventiva", "opcoes": ["não pode ser decretada de ofício pelo juiz, dependendo de requerimento do MP, do querelante, do assistente ou de representação da autoridade policial.", "pode ser decretada de ofício pelo juiz durante a investigação, mas não durante a ação penal.", "tem prazo máximo de 90 dias, após o qual o preso deve ser solto automaticamente, salvo se o juiz, de ofício, renovar a ordem em decisão fundamentada antes do fim do prazo.", "cabe em qualquer crime doloso, independentemente da pena.", "pode ser decretada para antecipar o cumprimento da pena."], "gabarito": 0, "explicacao": "Art. 311 do CPP, após a Lei 13.964/2019: vedada a decretação de ofício. A cada 90 dias, a necessidade deve ser revista, mas não há soltura automática (art. 316, parágrafo único; STF, SL 1.395). É vedada como antecipação de pena (art. 313, § 2º). Em regra, exige crime doloso com pena máxima superior a 4 anos."}, {"materia": "leg", "texto_base": "", "enunciado": "Pablo foi preso transportando cocaína de Salvador para Aracaju, em ônibus interestadual, e confessou que a entregaria nas imediações de uma escola. De acordo com o art. 40 da Lei 11.343/2006,", "opcoes": ["o transporte interestadual de drogas desloca a competência para a Justiça Federal.", "incidem as causas de aumento da interestadualidade e da prática nas imediações de estabelecimento de ensino, e, para a primeira, não é preciso que a droga efetivamente cruze a divisa (Súmula 587 do STJ).", "as causas de aumento do art. 40 são de 1/6 a metade, mas não podem ser aplicadas cumulativamente em nenhuma hipótese.", "a interestadualidade só se aplica se a droga efetivamente ultrapassar a divisa entre os estados, e a proximidade da escola exige que a entrega tenha sido feita a estudantes, o que não ocorreu, porque Pablo foi preso antes da entrega.", "a proximidade da escola só aumenta a pena se o crime ocorrer em horário de aula."], "gabarito": 1, "explicacao": "Súmula 587 do STJ: basta a demonstração inequívoca da intenção de realizar o tráfico interestadual. O art. 40, III e V, prevê aumento de 1/6 a 2/3. A competência é estadual, salvo transnacionalidade."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre o tráfico privilegiado (art. 33, § 4º, da Lei 11.343/2006), assinale a alternativa correta.", "opcoes": ["Permite redução fixa de metade da pena.", "Permite redução de 1/6 a 2/3 para agente primário, de bons antecedentes, que não se dedique a atividades criminosas nem integre organização criminosa, e não é considerado crime hediondo.", "Só se aplica se a quantidade de droga for inferior a 10 gramas.", "Exige que o agente seja menor de 21 anos.", "É considerado hediondo, por se tratar de modalidade de tráfico de drogas, mas permite redução de 1/6 a 2/3 para o agente primário e de bons antecedentes que não integre organização criminosa nem se dedique a atividades criminosas."], "gabarito": 1, "explicacao": "Art. 33, § 4º, da Lei de Drogas e art. 112, § 5º, da LEP (incluído pelo Pacote Anticrime): o tráfico privilegiado não é hediondo, como já decidira o STF no HC 118.533."}, {"materia": "leg", "texto_base": "", "enunciado": "Segundo a Lei 13.869/2019 (Abuso de Autoridade), para que as condutas nela descritas constituam crime, é necessário que o agente atue", "opcoes": ["por divergência na interpretação da lei ou na avaliação de fatos e provas, desde que dessa divergência resulte prejuízo concreto a outra pessoa.", "com dolo eventual, bastando assumir o risco de prejudicar alguém.", "independentemente de qualquer finalidade específica.", "com culpa, em qualquer de suas modalidades.", "com a finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou por mero capricho ou satisfação pessoal."], "gabarito": 4, "explicacao": "Art. 1º, § 1º, da Lei 13.869/2019 exige dolo específico. O § 2º diz que a divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade (crime de hermenêutica)."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre o crime de porte ilegal de arma de fogo de uso permitido (art. 14 da Lei 10.826/2003), assinale a alternativa correta.", "opcoes": ["É punido com detenção de 1 a 3 meses.", "É crime hediondo em qualquer circunstância.", "Configura-se ainda que a arma esteja desmuniciada, por ser crime de perigo abstrato, segundo o entendimento do STJ.", "É inafiançável em qualquer hipótese, conforme o parágrafo único do art. 14, que segue plenamente válido segundo o STF.", "Só se configura em via pública, nunca dentro de veículo."], "gabarito": 2, "explicacao": "O STJ entende que o porte de arma desmuniciada configura o crime, de perigo abstrato. O parágrafo único do art. 14 (inafiançabilidade) foi declarado inconstitucional pelo STF na ADI 3.112. Hediondo é o porte ou posse de arma de uso proibido (art. 16, § 2º). A pena do art. 14 é reclusão de 2 a 4 anos e multa."}, {"materia": "leg", "texto_base": "", "enunciado": "Um carcereiro submeteu um preso a intenso sofrimento físico como forma de castigo por mau comportamento na cela. O delegado responsável sabia do fato e nada fez para evitá-lo, embora tivesse o dever de agir. De acordo com a Lei 9.455/1997,", "opcoes": ["o carcereiro responde por maus-tratos, pois a vítima estava sob sua guarda, e o delegado não responde por nada.", "o delegado responde por prevaricação, e o carcereiro por lesão corporal grave.", "não há tortura, porque o castigo foi aplicado para manter a disciplina na unidade prisional.", "ambos respondem pela mesma pena de reclusão de 2 a 8 anos, sem distinção entre ação e omissão, pois o delegado tinha o dever legal de evitar o resultado.", "o carcereiro responde por tortura com aumento de pena por ser agente público, e o delegado responde pela omissão, com pena de detenção de 1 a 4 anos."], "gabarito": 4, "explicacao": "Art. 1º, II (tortura-castigo) e § 4º, I (aumento de 1/6 a 1/3 se cometido por agente público). O § 2º pune quem se omite diante das condutas, tendo o dever de evitá-las ou apurá-las, com detenção de 1 a 4 anos."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre a infiltração de agentes de polícia em tarefas de investigação (Lei 12.850/2013), assinale a alternativa correta.", "opcoes": ["Pode durar por prazo indeterminado, enquanto houver interesse da investigação.", "É permitida em qualquer infração penal, independentemente da pena.", "Depende de autorização judicial circunstanciada e sigilosa, só é admitida se a prova não puder ser produzida por outros meios disponíveis e tem prazo de até 6 meses, com renovações.", "Impõe ao agente infiltrado responsabilidade por qualquer crime praticado, ainda que inexigível conduta diversa.", "Pode ser determinada pelo delegado de polícia, independentemente de autorização judicial, em caso de urgência, devendo apenas comunicar o juiz em até 72 horas, que poderá ratificá-la ou não depois de ouvir o Ministério Público."], "gabarito": 2, "explicacao": "Arts. 10 e 13 da Lei 12.850/2013. A infiltração exige autorização judicial, tem caráter subsidiário (§ 2º) e prazo de até 6 meses, renovável (§ 3º). Não é punível o crime praticado pelo infiltrado quando inexigível conduta diversa (art. 13, parágrafo único)."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre a colaboração premiada (Lei 12.850/2013), assinale a alternativa correta.", "opcoes": ["Nenhuma sentença condenatória pode ser proferida com fundamento apenas nas declarações do colaborador.", "O colaborador pode manter o direito ao silêncio quanto aos fatos que revelar.", "O acordo pode ser celebrado apenas após o oferecimento da denúncia.", "O delegado de polícia não pode celebrar acordo de colaboração.", "O juiz participa das negociações entre as partes para garantir a voluntariedade do acordo e a legalidade das cláusulas."], "gabarito": 0, "explicacao": "Art. 4º, § 16, da Lei 12.850/2013. O juiz não participa das negociações (§ 6º). O colaborador renuncia ao direito ao silêncio (§ 14). O acordo pode ocorrer em qualquer fase, e o STF (ADI 5.508) admitiu que o delegado o celebre na fase de inquérito, com manifestação do MP."}, {"materia": "leg", "texto_base": "", "enunciado": "De acordo com a Lei 8.072/1990, é considerado crime hediondo", "opcoes": ["a lesão corporal grave praticada contra qualquer pessoa.", "o homicídio simples, ainda que não praticado em atividade típica de grupo de extermínio.", "o furto qualificado pelo concurso de pessoas.", "o roubo circunstanciado pelo emprego de arma de fogo.", "o tráfico de drogas, em sua forma simples."], "gabarito": 3, "explicacao": "Art. 1º, II, b, da Lei 8.072/1990 (após a Lei 13.964/2019). O tráfico é equiparado (art. 2º). O furto só é hediondo se qualificado pelo uso de explosivo. A lesão é hedionda quando gravíssima ou seguida de morte contra agentes de segurança (inciso I-A). O homicídio simples só é hediondo em atividade típica de grupo de extermínio."}, {"materia": "leg", "texto_base": "", "enunciado": "De acordo com o Estatuto da Criança e do Adolescente (Lei 8.069/1990), o adolescente apreendido em flagrante de ato infracional", "opcoes": ["pode permanecer em cela comum com adultos por até 5 dias, aguardando vaga em unidade de internação, desde que em local separado por grades e sob vigilância constante, conforme autorização do juiz da infância.", "deve ser, desde logo, encaminhado à autoridade policial competente, e sua apreensão comunicada de imediato à autoridade judiciária e à família ou pessoa indicada.", "deve ser conduzido algemado em compartimento fechado da viatura, em qualquer caso.", "fica sujeito à internação provisória pelo prazo máximo de 90 dias.", "não pode ser apreendido em flagrante, apenas por ordem judicial."], "gabarito": 1, "explicacao": "Arts. 107 e 172 do ECA. É vedado o transporte em compartimento fechado em condições atentatórias à dignidade (art. 178). A internação provisória tem prazo máximo de 45 dias (art. 108). O adolescente não pode ficar com adultos (art. 185)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre a inviolabilidade do domicílio (art. 5º, XI, da CF), assinale a alternativa correta.", "opcoes": ["O conceito de casa não abrange escritórios profissionais fechados ao público.", "Em caso de flagrante, o ingresso só é permitido durante o dia.", "O delegado de polícia pode expedir mandado de busca domiciliar em caso de urgência.", "Por determinação judicial, é possível ingressar a qualquer hora do dia ou da noite, e, sem consentimento do morador, apenas em caso de flagrante delito ocorrido durante o dia, desastre ou socorro.", "Sem consentimento do morador, é possível ingressar em flagrante delito, desastre ou para prestar socorro a qualquer hora, e por determinação judicial apenas durante o dia."], "gabarito": 4, "explicacao": "Art. 5º, XI, da CF. O STF estende o conceito de casa a escritórios e quartos de hotel ocupados. Mandado de busca é reserva de jurisdição."}, {"materia": "const", "texto_base": "", "enunciado": "Após a Emenda Constitucional 104/2019, a Constituição Federal passou a prever que às polícias penais, vinculadas ao órgão administrador do sistema penal da unidade federativa a que pertencem, cabe", "opcoes": ["a segurança dos estabelecimentos penais.", "a apuração das infrações penais cometidas dentro dos presídios, como polícia judiciária.", "o policiamento ostensivo nas áreas próximas aos presídios.", "a investigação dos crimes praticados por servidores do sistema prisional.", "a execução das penas, inclusive a concessão de progressão de regime."], "gabarito": 0, "explicacao": "Art. 144, § 5º-A, da CF: às polícias penais cabe a segurança dos estabelecimentos penais. A polícia judiciária é atribuição das polícias civis e federal; a execução da pena é jurisdicional."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre a extradição, de acordo com a Constituição Federal, assinale a alternativa correta.", "opcoes": ["O brasileiro nato pode ser extraditado por envolvimento comprovado em tráfico ilícito de entorpecentes, desde que o crime tenha sido cometido no exterior e haja tratado de reciprocidade.", "A extradição de estrangeiro depende apenas de decisão do Ministro da Justiça, sem participação do STF.", "O estrangeiro pode ser extraditado por crime político ou de opinião.", "O brasileiro naturalizado nunca pode ser extraditado.", "O brasileiro naturalizado pode ser extraditado por crime comum praticado antes da naturalização ou por comprovado envolvimento em tráfico ilícito de entorpecentes, na forma da lei."], "gabarito": 4, "explicacao": "Art. 5º, LI e LII, da CF. O nato nunca é extraditado. O estrangeiro não é extraditado por crime político ou de opinião. O pedido de extradição é julgado pelo STF (art. 102, I, g)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre os remédios constitucionais, assinale a alternativa correta.", "opcoes": ["O habeas data assegura o conhecimento e a retificação de informações relativas à pessoa do impetrante constantes de registros de entidades governamentais ou de caráter público.", "O habeas corpus é cabível contra punições disciplinares militares, inclusive para discutir o mérito da sanção imposta, já que a liberdade de locomoção do militar também é protegida pela Constituição.", "O mandado de segurança protege o direito de locomoção.", "A ação popular pode ser proposta por pessoa jurídica.", "O mandado de injunção é cabível para anular ato lesivo ao patrimônio público."], "gabarito": 0, "explicacao": "Art. 5º, LXXII, da CF. Não cabe HC em relação a punições disciplinares militares (art. 142, § 2º), salvo quanto à legalidade. A locomoção é protegida pelo HC. A ação popular é proposta por cidadão (Súmula 365 do STF). O mandado de injunção supre a falta de norma regulamentadora."}, {"materia": "const", "texto_base": "", "enunciado": "Uma Comissão Parlamentar de Inquérito (CPI) instalada no Congresso Nacional, por decisão fundamentada da maioria de seus membros, pode, por ato próprio,", "opcoes": ["determinar a busca e apreensão domiciliar na residência do investigado.", "determinar a quebra dos sigilos bancário, fiscal e de dados telefônicos de investigado.", "decretar a indisponibilidade dos bens do investigado.", "autorizar a interceptação das comunicações telefônicas do investigado, pelo prazo de 15 dias.", "decretar a prisão preventiva de investigado que se recuse a comparecer."], "gabarito": 1, "explicacao": "As CPIs têm poderes de investigação próprios das autoridades judiciais (art. 58, § 3º, da CF), mas o STF exclui as matérias sob reserva de jurisdição: prisão (salvo flagrante), busca domiciliar, interceptação telefônica e indisponibilidade de bens. A quebra de sigilos bancário, fiscal e de dados é permitida, com fundamentação."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre a nacionalidade, segundo a Constituição Federal, é cargo privativo de brasileiro nato o de", "opcoes": ["Ministro do Superior Tribunal de Justiça.", "Senador da República.", "Governador de Estado.", "Delegado de Polícia Federal.", "oficial das Forças Armadas."], "gabarito": 4, "explicacao": "Art. 12, § 3º, da CF: Presidente e Vice, Presidente da Câmara, Presidente do Senado, Ministro do STF, carreira diplomática, oficial das Forças Armadas e Ministro de Estado da Defesa. Senador comum, Ministro do STJ e Governador podem ser naturalizados."}, {"materia": "const", "texto_base": "", "enunciado": "De acordo com a Constituição Federal, a casa legislativa competente para processar e julgar o Presidente da República nos crimes de responsabilidade, após autorização da Câmara dos Deputados, é", "opcoes": ["o Senado Federal, sob a presidência do Presidente do STF.", "o Supremo Tribunal Federal, por maioria absoluta.", "o Congresso Nacional em sessão conjunta.", "o Superior Tribunal de Justiça.", "a Câmara dos Deputados."], "gabarito": 0, "explicacao": "Arts. 51, I, 52, I e parágrafo único, e 86 da CF. A Câmara autoriza por 2/3; o Senado julga, presidido pelo Presidente do STF. Nos crimes comuns, o julgamento é no STF."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre os direitos sociais e as garantias dos servidores militares, a Constituição Federal estabelece que ao militar são proibidas", "opcoes": ["a percepção de 13º salário.", "a sindicalização e a greve.", "a filiação a partido político em qualquer hipótese, mesmo depois de passar para a inatividade.", "a acumulação de qualquer cargo, inclusive de professor, mesmo com compatibilidade de horários.", "as férias anuais remuneradas."], "gabarito": 1, "explicacao": "Art. 142, § 3º, IV, da CF (aplicável aos militares dos estados por força do art. 42, § 1º). O militar da ativa não pode estar filiado a partido (inciso V), mas o inativo pode. A EC 101/2019 permitiu acumulação com cargo de professor ou da saúde."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre os atributos do ato administrativo, assinale a alternativa correta.", "opcoes": ["A presunção de legitimidade é absoluta, não admitindo prova em contrário, o que impede o particular de questionar o ato perante o Poder Judiciário antes de cumpri-lo.", "A tipicidade permite que a Administração crie atos não previstos em lei.", "A imperatividade está presente em todos os atos administrativos, inclusive nos enunciativos.", "A autoexecutoriedade permite que a Administração execute suas decisões sem prévia autorização judicial, quando a lei autorizar ou em situação de urgência.", "A autoexecutoriedade autoriza a cobrança de multas sem processo judicial de execução."], "gabarito": 3, "explicacao": "A presunção de legitimidade é relativa. Atos enunciativos e negociais não têm imperatividade. A tipicidade exige correspondência com figuras previstas em lei. A multa é exigível, mas sua cobrança forçada depende de execução fiscal."}, {"materia": "adm", "texto_base": "", "enunciado": "Um ato administrativo discricionário, válido e eficaz, tornou-se inconveniente ao interesse público. A Administração poderá", "opcoes": ["convalidá-lo, para corrigir o vício.", "revogá-lo, com efeitos ex nunc, respeitados os direitos adquiridos.", "anulá-lo, com efeitos ex tunc.", "apenas pedir ao Judiciário que o revogue.", "revogá-lo, com efeitos ex tunc, desfazendo todos os efeitos produzidos."], "gabarito": 1, "explicacao": "A revogação retira ato válido por conveniência e oportunidade, com efeitos para o futuro (ex nunc), e só pode ser feita pela própria Administração (Súmula 473 do STF). A anulação atinge ato ilegal."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre os poderes administrativos, assinale a alternativa correta.", "opcoes": ["O poder disciplinar alcança qualquer particular, ainda que sem vínculo com a Administração.", "O poder de polícia, em sentido estrito, pode ter fases delegadas a pessoas jurídicas de direito privado da Administração indireta, conforme o STF (Tema 532), exceto a de ordem de polícia.", "O poder de polícia é sempre vinculado, sem margem de discricionariedade.", "O poder regulamentar permite a edição de decretos autônomos para criar cargos públicos e órgãos da Administração, desde que não haja aumento de despesa, conforme o art. 84, VI, da Constituição.", "O poder hierárquico permite a avocação de competências exclusivas do subordinado."], "gabarito": 1, "explicacao": "No Tema 532 (RE 633.782), o STF admitiu a delegação das fases de consentimento, fiscalização e sanção a estatais de capital majoritariamente público que prestem serviço público em regime não concorrencial, mas não a da ordem de polícia. O poder disciplinar alcança quem tem vínculo especial. Não se avoca competência exclusiva. Decreto autônomo não cria cargos (art. 84, VI, da CF)."}, {"materia": "adm", "texto_base": "", "enunciado": "Uma viatura da Polícia Civil, em perseguição, colidiu com o carro de um particular que estava regularmente estacionado. Sobre a responsabilidade civil, é correto afirmar que", "opcoes": ["o Estado responde objetivamente pelos danos, assegurado o direito de regresso contra o agente nos casos de dolo ou culpa.", "o particular deve processar diretamente o policial que dirigia a viatura.", "não há responsabilidade, pois a perseguição era um ato lícito no estrito cumprimento do dever legal.", "o policial e o Estado respondem solidariamente, de forma objetiva.", "o Estado só responde se o particular provar a culpa do policial, pois a responsabilidade por atos de agentes de segurança é subjetiva, na modalidade culpa do serviço."], "gabarito": 0, "explicacao": "Art. 37, § 6º, da CF: responsabilidade objetiva do Estado, inclusive por atos lícitos. No Tema 940, o STF fixou a teoria da dupla garantia: a ação é proposta contra o Estado, que tem regresso contra o agente culpado."}, {"materia": "adm", "texto_base": "", "enunciado": "De acordo com a Lei 8.429/1992, com as alterações da Lei 14.230/2021, os atos de improbidade administrativa", "opcoes": ["admitem a forma culposa nos casos de dano ao erário.", "podem ser punidos com pena de prisão aplicada na própria ação de improbidade.", "exigem dolo para sua configuração, em todas as modalidades.", "são imprescritíveis em todas as hipóteses.", "configuram-se pela mera ilegalidade, independentemente de dolo."], "gabarito": 2, "explicacao": "Após a Lei 14.230/2021, só há improbidade dolosa (art. 1º, §§ 1º a 3º). A prescrição é de 8 anos (art. 23). A imprescritibilidade vale apenas para o ressarcimento por ato doloso (Tema 897 do STF). A ação é cível."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre os princípios da Administração Pública, assinale a alternativa correta.", "opcoes": ["O princípio da legalidade permite ao administrador fazer tudo o que a lei não proíbe.", "O princípio da eficiência foi incluído no texto original da Constituição de 1988.", "A nomeação de cônjuge da autoridade nomeante para cargo em comissão viola a Constituição, conforme a Súmula Vinculante 13.", "O princípio da publicidade impede qualquer restrição de acesso a informações públicas, inclusive às relativas à segurança do Estado.", "A impessoalidade permite que obras públicas tragam o nome do governante que as realizou."], "gabarito": 2, "explicacao": "Súmula Vinculante 13 (nepotismo). A publicidade admite sigilo previsto em lei. A eficiência veio com a EC 19/1998. Na Administração, legalidade é fazer só o que a lei autoriza. O art. 37, § 1º, veda a promoção pessoal."}, {"materia": "adm", "texto_base": "", "enunciado": "Na Lei 14.133/2021 (Licitações e Contratos), a modalidade de licitação obrigatória para aquisição de bens e serviços comuns, cujo critério de julgamento pode ser o de menor preço ou o de maior desconto, é", "opcoes": ["o concurso.", "a concorrência.", "o diálogo competitivo.", "o pregão.", "o leilão."], "gabarito": 3, "explicacao": "Art. 6º, XLI, e art. 29 da Lei 14.133/2021. O concurso escolhe trabalho técnico, científico ou artístico; o leilão aliena bens; o diálogo competitivo serve a contratações inovadoras."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre os agentes públicos e o regime constitucional, assinale a alternativa correta.", "opcoes": ["A acumulação de dois cargos técnicos ou científicos é permitida, havendo compatibilidade de horários, desde que a soma das remunerações não ultrapasse o teto constitucional aplicado ao servidor e haja autorização do chefe do órgão.", "O servidor em estágio probatório não pode ser exonerado.", "A estabilidade é adquirida após 2 anos de efetivo exercício.", "O servidor estável só perde o cargo em virtude de sentença judicial transitada em julgado, processo administrativo com ampla defesa ou avaliação periódica de desempenho, na forma de lei complementar.", "Os cargos em comissão podem ser ocupados para funções técnicas e operacionais, sem limite."], "gabarito": 3, "explicacao": "Art. 41, § 1º, da CF. A estabilidade vem após 3 anos e avaliação especial de desempenho. O servidor em estágio probatório pode ser exonerado se reprovado. Cargos em comissão destinam-se a direção, chefia e assessoramento. Admite-se um cargo técnico com um de professor (art. 37, XVI)."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa comprou mercadorias a prazo por R$ 20.000,00. O lançamento contábil correto dessa operação é", "opcoes": ["D – Mercadorias; C – Caixa.", "D – Clientes; C – Mercadorias.", "D – Custo das Mercadorias Vendidas; C – Fornecedores.", "D – Fornecedores; C – Mercadorias.", "D – Mercadorias (Estoques); C – Fornecedores."], "gabarito": 4, "explicacao": "A compra a prazo aumenta o ativo (estoques: débito) e o passivo (fornecedores: crédito)."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa apresentava estoque inicial de R$ 30.000,00, fez compras de R$ 50.000,00 e terminou o período com estoque final de R$ 20.000,00. As vendas foram de R$ 100.000,00. O lucro bruto foi de", "opcoes": ["R$ 50.000,00.", "R$ 20.000,00.", "R$ 60.000,00.", "R$ 70.000,00.", "R$ 40.000,00."], "gabarito": 4, "explicacao": "CMV = EI + C − EF = 30.000 + 50.000 − 20.000 = 60.000. Lucro bruto = 100.000 − 60.000 = 40.000."}, {"materia": "cont", "texto_base": "", "enunciado": "Assinale a alternativa que apresenta apenas contas de natureza devedora.", "opcoes": ["Depreciação Acumulada, Duplicatas a Receber e Salários a Pagar.", "Fornecedores, Capital Social e Receitas de Vendas.", "Caixa, Fornecedores e Lucros Acumulados.", "Caixa, Estoques e Despesas com Salários.", "Capital Social, Estoques e Receita de Serviços."], "gabarito": 3, "explicacao": "Ativos e despesas têm natureza devedora. Passivos, patrimônio líquido, receitas e contas retificadoras do ativo (como Depreciação Acumulada) têm natureza credora."}, {"materia": "cont", "texto_base": "", "enunciado": "Em determinado mês, uma empresa prestou serviços de R$ 30.000,00, recebendo R$ 10.000,00 à vista e o restante para o mês seguinte. No mesmo mês, pagou R$ 6.000,00 de salários referentes ao mês anterior e incorreu em R$ 8.000,00 de salários do próprio mês, que só serão pagos no mês seguinte. Pelo regime de competência, o resultado do mês foi", "opcoes": ["lucro de R$ 4.000,00.", "lucro de R$ 24.000,00.", "lucro de R$ 22.000,00.", "lucro de R$ 16.000,00.", "prejuízo de R$ 4.000,00."], "gabarito": 2, "explicacao": "Competência: receita de 30.000 (toda a prestada no mês) menos despesa de 8.000 (salários do próprio mês) = 22.000. O pagamento de 6.000 refere-se ao mês anterior. Pelo regime de caixa seria 10.000 − 6.000 = 4.000."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa tinha 100 unidades em estoque a R$ 10,00 cada. Comprou mais 100 unidades a R$ 14,00 cada e, depois, vendeu 150 unidades. Pelo método PEPS (primeiro que entra, primeiro que sai), o custo das mercadorias vendidas foi de", "opcoes": ["R$ 1.700,00.", "R$ 1.900,00.", "R$ 1.800,00.", "R$ 1.500,00.", "R$ 2.100,00."], "gabarito": 0, "explicacao": "PEPS: saem primeiro as 100 unidades a R$ 10 (R$ 1.000) e depois 50 a R$ 14 (R$ 700). CMV = R$ 1.700. Pela média ponderada (R$ 12), seria R$ 1.800; pelo UEPS, R$ 1.900."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa apresentou Ativo Circulante de R$ 180.000,00, Estoques de R$ 60.000,00 e Passivo Circulante de R$ 120.000,00. Os índices de liquidez corrente e de liquidez seca são, respectivamente,", "opcoes": ["2,0 e 1,0.", "0,67 e 1,0.", "1,5 e 1,0.", "1,5 e 0,5.", "1,0 e 1,5."], "gabarito": 2, "explicacao": "Liquidez corrente = 180.000 / 120.000 = 1,5. Liquidez seca = (180.000 − 60.000) / 120.000 = 1,0."}, {"materia": "cont", "texto_base": "", "enunciado": "De acordo com a Lei 6.404/1976, os elementos do Balanço Patrimonial classificados no ativo são dispostos", "opcoes": ["em ordem decrescente de grau de liquidez.", "em ordem alfabética das contas.", "em ordem decrescente de valor.", "pela ordem cronológica de aquisição.", "em ordem crescente de grau de liquidez."], "gabarito": 0, "explicacao": "Art. 178 da Lei 6.404/1976: no ativo, as contas são dispostas em ordem decrescente de grau de liquidez."}, {"materia": "cont", "texto_base": "", "enunciado": "O pagamento antecipado de 12 meses de aluguel, no início do exercício, deve ser registrado inicialmente como", "opcoes": ["receita diferida, no passivo não circulante.", "passivo circulante, como aluguel a pagar.", "redução do patrimônio líquido, como reserva de lucros.", "despesa antecipada, no ativo, apropriada ao resultado mês a mês, pelo regime de competência.", "despesa do mês do pagamento, pelo regime de caixa, porque o valor saiu integralmente do caixa da empresa."], "gabarito": 3, "explicacao": "Pelo regime de competência, o pagamento antecipado gera um ativo (despesas antecipadas), que vira despesa conforme os meses transcorrem."}, {"materia": "est", "texto_base": "", "enunciado": "Os tempos (em minutos) de resposta de 7 ocorrências foram: 12, 15, 8, 20, 15, 10, 25. A mediana e a moda desses dados são, respectivamente,", "opcoes": ["12 e 15.", "14,4 e 15.", "15 e 12.", "15 e 15.", "15,0 e 20."], "gabarito": 3, "explicacao": "Ordenando: 8, 10, 12, 15, 15, 20, 25. A mediana é o 4º valor (15); a moda é 15 (aparece duas vezes). A média seria 105/7 = 15."}, {"materia": "est", "texto_base": "", "enunciado": "Um conjunto de dados tem média 50 e desvio-padrão 10. Se cada valor for multiplicado por 2 e, em seguida, somado a 5, a nova média e o novo desvio-padrão serão, respectivamente,", "opcoes": ["105 e 25.", "105 e 20.", "100 e 20.", "55 e 10.", "105 e 10."], "gabarito": 1, "explicacao": "Média: 2 × 50 + 5 = 105. O desvio-padrão é afetado só pela multiplicação: 2 × 10 = 20; somar uma constante não altera a dispersão."}, {"materia": "est", "texto_base": "", "enunciado": "Em uma cidade, 30% das ocorrências acontecem à noite. Das ocorrências noturnas, 60% envolvem roubo; das diurnas, 20% envolvem roubo. Sorteada uma ocorrência de roubo, a probabilidade de que ela tenha acontecido à noite é", "opcoes": ["18/100.", "3/5.", "1/2.", "9/16.", "3/10."], "gabarito": 3, "explicacao": "P(roubo) = 0,3 × 0,6 + 0,7 × 0,2 = 0,18 + 0,14 = 0,32. Pelo teorema de Bayes, P(noite | roubo) = 0,18 / 0,32 = 9/16."}, {"materia": "est", "texto_base": "", "enunciado": "Em uma delegacia, 40% das ocorrências são de furto e 25% são de roubo, sendo os eventos mutuamente exclusivos. Escolhida uma ocorrência ao acaso, a probabilidade de que seja de furto ou de roubo é", "opcoes": ["90%.", "35%.", "15%.", "10%.", "65%."], "gabarito": 4, "explicacao": "Eventos mutuamente exclusivos: P(F ∪ R) = 0,40 + 0,25 = 0,65."}, {"materia": "est", "texto_base": "", "enunciado": "Uma variável tem distribuição normal com média 100 e desvio-padrão 15. Aproximadamente que percentual dos valores está entre 70 e 130?", "opcoes": ["68%.", "50%.", "34%.", "99,7%.", "95%."], "gabarito": 4, "explicacao": "70 e 130 estão a 2 desvios-padrão da média (100 ± 30). Pela regra empírica, cerca de 95% dos valores ficam entre μ − 2σ e μ + 2σ."}, {"materia": "est", "texto_base": "", "enunciado": "A variância dos valores 2, 4, 6, 8 e 10, considerados como população, é", "opcoes": ["2,83.", "10.", "8.", "6.", "4."], "gabarito": 2, "explicacao": "Média = 6. Desvios ao quadrado: 16, 4, 0, 4, 16 (soma 40). Variância populacional = 40/5 = 8. A amostral seria 40/4 = 10."}, {"materia": "est", "texto_base": "", "enunciado": "Em uma distribuição de dados com forte assimetria positiva (cauda longa à direita), em geral vale a relação", "opcoes": ["mediana < moda < média.", "média < moda < mediana.", "média < mediana < moda.", "moda < mediana < média.", "média = mediana = moda."], "gabarito": 3, "explicacao": "Na assimetria positiva, os valores extremos à direita puxam a média para cima: moda < mediana < média."}, {"materia": "est", "texto_base": "", "enunciado": "Em uma pesquisa, a população foi dividida em grupos homogêneos internamente (por exemplo, por bairro) e, de cada grupo, sorteou-se uma amostra proporcional ao seu tamanho. Essa técnica é a amostragem", "opcoes": ["por conglomerados.", "por conveniência.", "sistemática.", "estratificada.", "por cotas sem sorteio."], "gabarito": 3, "explicacao": "Na amostragem estratificada, a população é dividida em estratos homogêneos e sorteiam-se elementos de cada estrato. Nos conglomerados, sorteiam-se grupos inteiros; na sistemática, de k em k elementos."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('policial', date '2026-11-22', 'Simulado 5 · Policial', 'AOCP', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado 5 · Policial já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

do $$
declare r record; src bigint; nid bigint; est text; dur integer;
begin
  for r in select * from (values
      ('enem', 'Simulado 1 · Enem', 'Simulado 2 · Enem'),
      ('fiscal', 'Simulado 1 · Fiscal', 'Simulado 2 · Fiscal'),
      ('tribunais', 'Simulado 1 · Tribunais', 'Simulado 2 · Tribunais'),
      ('administrativa', 'Simulado 1 · Administrativa', 'Simulado 2 · Administrativa'),
      ('saude', 'Simulado 1 · Saúde', 'Simulado 3 · Saúde')) v(trilha, origem, novo)
  loop
    if exists (select 1 from public.simulados where trilha = r.trilha and data = date '2026-11-22') then
      raise notice '%: já existe simulado em 22/11, nada a fazer.', r.trilha;
      continue;
    end if;
    src := null;
    select s.id, s.estilo, s.duracao_min into src, est, dur from public.simulados s
     where s.trilha = r.trilha and s.titulo = r.origem
       and exists (select 1 from public.simulado_questoes q where q.simulado_id = s.id)
     order by s.data desc limit 1;
    if src is null then raise notice '%: não achei o "%".', r.trilha, r.origem; continue; end if;
    insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
    values (r.trilha, date '2026-11-22', r.novo, est, dur, true) returning id into nid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select nid, q.ordem, q.materia, q.texto_base, q.enunciado, x.opc, x.gab, q.explicacao
      from public.simulado_questoes q
      cross join lateral (
        select jsonb_agg(e.v order by e.r) as opc,
               (array_position(array_agg(e.i order by e.r), q.gabarito::bigint) - 1)::smallint as gab
          from (select t.v, t.i - 1 as i, random() as r from jsonb_array_elements(q.opcoes) with ordinality t(v, i)) e
      ) x
     where q.simulado_id = src;
    raise notice '%: "%" criado para 22/11 (id %), a partir do simulado %.', r.trilha, r.novo, nid, src;
  end loop;
end $$;

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "A cada nova tecnologia, repete-se a mesma profecia: agora, sim, o trabalho humano será dispensável. Aconteceu com o tear mecânico, com o computador pessoal, com a internet. Em todos os casos, alguns ofícios de fato desapareceram, mas outros surgiram — e, sobretudo, muitos dos antigos se transformaram. O datilógrafo não sobreviveu ao processador de textos; o escritor, sim.\n\nA inteligência artificial reacende a profecia com força inédita, porque, pela primeira vez, a máquina parece invadir o território que julgávamos exclusivamente nosso: o da linguagem e do raciocínio. Convém, porém, desconfiar tanto do pânico quanto do deslumbramento. Ferramentas que redigem, resumem e traduzem não eliminam a necessidade de quem saiba o que pedir, avaliar o que recebeu e responder pelo resultado.\n\nNo serviço público, essa distinção é decisiva. Um parecer, uma decisão administrativa, uma resposta ao cidadão não valem apenas pelo texto que contêm, mas pela responsabilidade de quem os assina. A tecnologia pode acelerar o caminho; não pode, contudo, assumir a autoria.", "enunciado": "A tese central do texto é a de que", "opcoes": ["as profecias sobre o fim do trabalho humano sempre se confirmaram ao longo da história.", "a inteligência artificial eliminará a maior parte dos empregos ligados à linguagem e ao raciocínio, como já ocorreu com o tear.", "o serviço público deve proibir o uso de ferramentas que redigem e resumem textos.", "a inteligência artificial pode acelerar tarefas, mas não substitui o julgamento e a responsabilidade humanos.", "o deslumbramento com a tecnologia é mais perigoso do que o pânico diante dela."], "gabarito": 3, "explicacao": "O texto conclui que a tecnologia 'pode acelerar o caminho; não pode, contudo, assumir a autoria', e que é preciso alguém que saiba pedir, avaliar e responder pelo resultado."}, {"materia": "port", "texto_base": "A cada nova tecnologia, repete-se a mesma profecia: agora, sim, o trabalho humano será dispensável. Aconteceu com o tear mecânico, com o computador pessoal, com a internet. Em todos os casos, alguns ofícios de fato desapareceram, mas outros surgiram — e, sobretudo, muitos dos antigos se transformaram. O datilógrafo não sobreviveu ao processador de textos; o escritor, sim.\n\nA inteligência artificial reacende a profecia com força inédita, porque, pela primeira vez, a máquina parece invadir o território que julgávamos exclusivamente nosso: o da linguagem e do raciocínio. Convém, porém, desconfiar tanto do pânico quanto do deslumbramento. Ferramentas que redigem, resumem e traduzem não eliminam a necessidade de quem saiba o que pedir, avaliar o que recebeu e responder pelo resultado.\n\nNo serviço público, essa distinção é decisiva. Um parecer, uma decisão administrativa, uma resposta ao cidadão não valem apenas pelo texto que contêm, mas pela responsabilidade de quem os assina. A tecnologia pode acelerar o caminho; não pode, contudo, assumir a autoria.", "enunciado": "No primeiro parágrafo, o exemplo do datilógrafo e do escritor é usado para", "opcoes": ["ilustrar que algumas funções desaparecem com a tecnologia, enquanto outras se transformam e permanecem.", "mostrar que o escritor perdeu espaço para o processador de textos, assim como o datilógrafo perdeu o seu.", "provar que todos os ofícios ligados à escrita foram extintos pelo computador.", "criticar a resistência dos trabalhadores às novas tecnologias.", "demonstrar que a profecia sobre o fim do trabalho estava correta."], "gabarito": 0, "explicacao": "O datilógrafo (ofício que desapareceu) contrasta com o escritor (que sobreviveu e se transformou), exemplificando a afirmação anterior."}, {"materia": "port", "texto_base": "A cada nova tecnologia, repete-se a mesma profecia: agora, sim, o trabalho humano será dispensável. Aconteceu com o tear mecânico, com o computador pessoal, com a internet. Em todos os casos, alguns ofícios de fato desapareceram, mas outros surgiram — e, sobretudo, muitos dos antigos se transformaram. O datilógrafo não sobreviveu ao processador de textos; o escritor, sim.\n\nA inteligência artificial reacende a profecia com força inédita, porque, pela primeira vez, a máquina parece invadir o território que julgávamos exclusivamente nosso: o da linguagem e do raciocínio. Convém, porém, desconfiar tanto do pânico quanto do deslumbramento. Ferramentas que redigem, resumem e traduzem não eliminam a necessidade de quem saiba o que pedir, avaliar o que recebeu e responder pelo resultado.\n\nNo serviço público, essa distinção é decisiva. Um parecer, uma decisão administrativa, uma resposta ao cidadão não valem apenas pelo texto que contêm, mas pela responsabilidade de quem os assina. A tecnologia pode acelerar o caminho; não pode, contudo, assumir a autoria.", "enunciado": "Em “Convém, porém, desconfiar tanto do pânico quanto do deslumbramento”, a conjunção “porém” estabelece relação de", "opcoes": ["condição para que a profecia se realize.", "adição de um novo exemplo histórico.", "oposição em relação à ideia de que a IA invade um território exclusivamente humano.", "conclusão em relação ao parágrafo anterior, resumindo a ideia de que a profecia se confirmou.", "explicação da força inédita da profecia."], "gabarito": 2, "explicacao": "'Porém' é adversativa: depois de reconhecer a força da profecia, o autor contrapõe a necessidade de cautela."}, {"materia": "port", "texto_base": "A cada nova tecnologia, repete-se a mesma profecia: agora, sim, o trabalho humano será dispensável. Aconteceu com o tear mecânico, com o computador pessoal, com a internet. Em todos os casos, alguns ofícios de fato desapareceram, mas outros surgiram — e, sobretudo, muitos dos antigos se transformaram. O datilógrafo não sobreviveu ao processador de textos; o escritor, sim.\n\nA inteligência artificial reacende a profecia com força inédita, porque, pela primeira vez, a máquina parece invadir o território que julgávamos exclusivamente nosso: o da linguagem e do raciocínio. Convém, porém, desconfiar tanto do pânico quanto do deslumbramento. Ferramentas que redigem, resumem e traduzem não eliminam a necessidade de quem saiba o que pedir, avaliar o que recebeu e responder pelo resultado.\n\nNo serviço público, essa distinção é decisiva. Um parecer, uma decisão administrativa, uma resposta ao cidadão não valem apenas pelo texto que contêm, mas pela responsabilidade de quem os assina. A tecnologia pode acelerar o caminho; não pode, contudo, assumir a autoria.", "enunciado": "No trecho “o datilógrafo não sobreviveu ao processador de textos; o escritor, sim”, a vírgula depois de “escritor” indica", "opcoes": ["a intercalação de um aposto explicativo.", "a separação de orações coordenadas assindéticas.", "a presença de um vocativo.", "a omissão do verbo “sobreviveu”, já expresso antes.", "a separação entre sujeito e predicado, obrigatória nesse caso."], "gabarito": 3, "explicacao": "A vírgula marca a elipse (zeugma) do verbo: 'o escritor sobreviveu, sim'."}, {"materia": "port", "texto_base": "A cada nova tecnologia, repete-se a mesma profecia: agora, sim, o trabalho humano será dispensável. Aconteceu com o tear mecânico, com o computador pessoal, com a internet. Em todos os casos, alguns ofícios de fato desapareceram, mas outros surgiram — e, sobretudo, muitos dos antigos se transformaram. O datilógrafo não sobreviveu ao processador de textos; o escritor, sim.\n\nA inteligência artificial reacende a profecia com força inédita, porque, pela primeira vez, a máquina parece invadir o território que julgávamos exclusivamente nosso: o da linguagem e do raciocínio. Convém, porém, desconfiar tanto do pânico quanto do deslumbramento. Ferramentas que redigem, resumem e traduzem não eliminam a necessidade de quem saiba o que pedir, avaliar o que recebeu e responder pelo resultado.\n\nNo serviço público, essa distinção é decisiva. Um parecer, uma decisão administrativa, uma resposta ao cidadão não valem apenas pelo texto que contêm, mas pela responsabilidade de quem os assina. A tecnologia pode acelerar o caminho; não pode, contudo, assumir a autoria.", "enunciado": "Em “quem saiba o que pedir, avaliar o que recebeu e responder pelo resultado”, o verbo “saber” está no subjuntivo porque", "opcoes": ["a oração expressa um fato hipotético, referente a uma pessoa indeterminada.", "exprime uma ordem dirigida ao leitor.", "a regência do verbo “eliminar”, que aparece antes na mesma frase, exige o modo subjuntivo.", "indica ação concluída no passado.", "concorda com o sujeito “ferramentas”."], "gabarito": 0, "explicacao": "'Quem saiba' refere-se a alguém não identificado, cuja existência é tratada como necessidade (hipótese); por isso, o subjuntivo."}, {"materia": "port", "texto_base": "A cada nova tecnologia, repete-se a mesma profecia: agora, sim, o trabalho humano será dispensável. Aconteceu com o tear mecânico, com o computador pessoal, com a internet. Em todos os casos, alguns ofícios de fato desapareceram, mas outros surgiram — e, sobretudo, muitos dos antigos se transformaram. O datilógrafo não sobreviveu ao processador de textos; o escritor, sim.\n\nA inteligência artificial reacende a profecia com força inédita, porque, pela primeira vez, a máquina parece invadir o território que julgávamos exclusivamente nosso: o da linguagem e do raciocínio. Convém, porém, desconfiar tanto do pânico quanto do deslumbramento. Ferramentas que redigem, resumem e traduzem não eliminam a necessidade de quem saiba o que pedir, avaliar o que recebeu e responder pelo resultado.\n\nNo serviço público, essa distinção é decisiva. Um parecer, uma decisão administrativa, uma resposta ao cidadão não valem apenas pelo texto que contêm, mas pela responsabilidade de quem os assina. A tecnologia pode acelerar o caminho; não pode, contudo, assumir a autoria.", "enunciado": "A palavra “inédita”, em “com força inédita”, pode ser substituída, sem prejuízo de sentido, por", "opcoes": ["passageira.", "sem precedentes.", "previsível.", "moderada.", "costumeira."], "gabarito": 1, "explicacao": "'Inédita' significa nunca vista antes: 'sem precedentes'."}, {"materia": "port", "texto_base": "A cada nova tecnologia, repete-se a mesma profecia: agora, sim, o trabalho humano será dispensável. Aconteceu com o tear mecânico, com o computador pessoal, com a internet. Em todos os casos, alguns ofícios de fato desapareceram, mas outros surgiram — e, sobretudo, muitos dos antigos se transformaram. O datilógrafo não sobreviveu ao processador de textos; o escritor, sim.\n\nA inteligência artificial reacende a profecia com força inédita, porque, pela primeira vez, a máquina parece invadir o território que julgávamos exclusivamente nosso: o da linguagem e do raciocínio. Convém, porém, desconfiar tanto do pânico quanto do deslumbramento. Ferramentas que redigem, resumem e traduzem não eliminam a necessidade de quem saiba o que pedir, avaliar o que recebeu e responder pelo resultado.\n\nNo serviço público, essa distinção é decisiva. Um parecer, uma decisão administrativa, uma resposta ao cidadão não valem apenas pelo texto que contêm, mas pela responsabilidade de quem os assina. A tecnologia pode acelerar o caminho; não pode, contudo, assumir a autoria.", "enunciado": "No último parágrafo, a expressão “essa distinção” retoma a diferença entre", "opcoes": ["os ofícios que desapareceram e os que surgiram.", "o pânico e o deslumbramento diante da tecnologia, citados no segundo parágrafo.", "produzir um texto e responder por ele com julgamento próprio.", "a linguagem humana e a linguagem das máquinas.", "o tear mecânico e o computador pessoal."], "gabarito": 2, "explicacao": "O parágrafo anterior distingue a ferramenta que redige do ser humano que sabe pedir, avaliar e responder pelo resultado."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que a colocação do pronome oblíquo está de acordo com a norma-padrão.", "opcoes": ["Me informaram ontem que o prazo do edital foi prorrogado.", "Nunca se esqueça de anexar os documentos ao processo.", "Tudo resolveu-se depois da audiência.", "Quando avisaram-me, o edital já tinha saído.", "O servidor não lembrou-se do horário da reunião."], "gabarito": 1, "explicacao": "Palavras negativas (nunca, não), conjunções subordinativas (quando) e pronomes indefinidos (tudo) atraem o pronome (próclise). Não se inicia período com pronome oblíquo átono."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa correta quanto à concordância nominal.", "opcoes": ["Bastante candidatos faltaram à prova.", "Seguem anexas as certidões solicitadas pelo setor.", "É proibido a entrada de pessoas sem crachá.", "As servidoras ficaram meias preocupadas com o prazo.", "Seguem anexo as cópias dos contratos."], "gabarito": 1, "explicacao": "'Anexo' concorda com o substantivo (anexas as certidões). 'É proibida a entrada' (com artigo, concorda). 'Meio' advérbio é invariável. 'Bastantes candidatos' (adjetivo, varia)."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que todas as palavras estão grafadas corretamente.", "opcoes": ["exceção, privilégio, beneficente", "exceção, previlégio, beneficiente", "exceção, privilégio, beneficiente", "excessão, previlégio, beneficente", "excessão, privilégio, beneficiente"], "gabarito": 0, "explicacao": "Grafias corretas: exceção, privilégio, beneficente."}, {"materia": "port", "texto_base": "", "enunciado": "Na frase “Os documentos que o diretor mencionou estão na pasta”, a palavra “que” é", "opcoes": ["conjunção causal.", "advérbio de intensidade.", "conjunção integrante, introduzindo oração substantiva.", "pronome relativo, com função de objeto direto.", "pronome relativo, com função de sujeito."], "gabarito": 3, "explicacao": "'Que' retoma 'documentos' (pronome relativo) e funciona como objeto direto de 'mencionou' (o diretor mencionou os documentos)."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que o uso do acento indicativo de crase é facultativo.", "opcoes": ["Entreguei o relatório à minha chefe.", "Ele se dedicou à pesquisa durante anos.", "Saímos às 18 horas.", "Vou à Bahia no próximo mês.", "Fiz referência à lei aprovada ontem."], "gabarito": 0, "explicacao": "Antes de pronome possessivo feminino singular, o artigo é facultativo, e a crase também. Nos demais casos, a crase é obrigatória."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que o verbo está corretamente flexionado.", "opcoes": ["Se ele propor uma solução, a equipe vai aceitar.", "Se o servidor vir o erro a tempo, poderá corrigi-lo.", "Se a comissão manter a decisão, haverá recurso.", "Os técnicos reaveram os arquivos perdidos.", "Quando o diretor ver o relatório final, vai aprová-lo."], "gabarito": 1, "explicacao": "Futuro do subjuntivo de 'ver' é 'vir'; de 'propor', 'propuser'; de 'manter', 'mantiver'. 'Reaver' no pretérito: 'reouveram'."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa que apresenta voz passiva sintética.", "opcoes": ["Trabalha-se muito no fim do ano.", "Os candidatos se cumprimentaram na entrada.", "O relatório foi entregue pelo estagiário.", "Vendem-se lotes no centro da cidade.", "Precisa-se de técnicos em informática."], "gabarito": 3, "explicacao": "'Vendem-se lotes' = 'lotes são vendidos' (VTD + se apassivador). Com VTI ou VI, o 'se' indetermina o sujeito. 'Foi entregue' é passiva analítica; 'se cumprimentaram' é reflexiva recíproca."}, {"materia": "port", "texto_base": "", "enunciado": "Em um ofício dirigido a um Ministro de Estado, o pronome de tratamento e o vocativo adequados são, respectivamente,", "opcoes": ["Vossa Magnificência e “Senhor Ministro,”.", "Vossa Excelência e “Ilustríssimo Senhor Ministro,”.", "Vossa Senhoria e “Excelentíssimo Senhor Ministro,”.", "Vossa Excelência e “Senhor Ministro,”.", "Sua Excelência e “Prezado Ministro,”."], "gabarito": 3, "explicacao": "Segundo o Manual de Redação da Presidência da República, usa-se Vossa Excelência para Ministros, com o vocativo 'Senhor Ministro,'. 'Ilustríssimo' e 'Digníssimo' foram abolidos."}, {"materia": "rl", "texto_base": "", "enunciado": "A negação da proposição “O servidor é pontual e cumpre metas” é:", "opcoes": ["Se o servidor é pontual, então cumpre metas.", "O servidor não é pontual e, mesmo assim, cumpre metas.", "O servidor é pontual ou cumpre metas.", "O servidor não é pontual e não cumpre metas.", "O servidor não é pontual ou não cumpre metas."], "gabarito": 4, "explicacao": "~(p ∧ q) ≡ ~p ∨ ~q (lei de De Morgan)."}, {"materia": "rl", "texto_base": "", "enunciado": "Considere: “Se chove, então a rua fica molhada”. É logicamente equivalente a essa proposição:", "opcoes": ["Chove ou a rua fica molhada.", "Chove e a rua não fica molhada.", "Não chove ou a rua fica molhada.", "Se a rua fica molhada, então chove.", "Se não chove, então a rua não fica molhada."], "gabarito": 2, "explicacao": "p → q ≡ ~p ∨ q. A recíproca e a inversa não são equivalentes; 'chove e a rua não fica molhada' é a negação."}, {"materia": "rl", "texto_base": "", "enunciado": "Todos os analistas são servidores. Alguns servidores são concursados. Logo,", "opcoes": ["alguns analistas são concursados, pois todos os analistas são servidores.", "todos os servidores são analistas.", "todos os concursados são analistas.", "nenhum analista é concursado.", "não se pode concluir, com certeza, que algum analista seja concursado."], "gabarito": 4, "explicacao": "Os servidores concursados podem não ser analistas. Nenhuma relação entre analistas e concursados é garantida pelas premissas."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma proposição composta que é sempre verdadeira, quaisquer que sejam os valores lógicos das proposições simples que a compõem, é chamada de", "opcoes": ["negação.", "contingência.", "tautologia.", "contradição.", "equivalência."], "gabarito": 2, "explicacao": "Tautologia: sempre verdadeira (ex.: p ∨ ~p). Contradição: sempre falsa. Contingência: pode ser V ou F."}, {"materia": "rl", "texto_base": "", "enunciado": "Quantos anagramas da palavra PROVA começam por vogal?", "opcoes": ["60.", "12.", "120.", "24.", "48."], "gabarito": 4, "explicacao": "Vogais em PROVA: O e A (2 opções para a 1ª letra). As outras 4 letras permutam: 4! = 24. Total: 2 × 24 = 48."}, {"materia": "rl", "texto_base": "", "enunciado": "De um grupo de 8 servidores, deseja-se formar uma comissão de 3 membros. O número de comissões possíveis é", "opcoes": ["512.", "336.", "24.", "56.", "40."], "gabarito": 3, "explicacao": "C(8,3) = 8 × 7 × 6 / 3! = 336 / 6 = 56. A ordem não importa."}, {"materia": "rl", "texto_base": "", "enunciado": "Ao lançar dois dados comuns, não viciados, a probabilidade de que a soma dos resultados seja 7 é", "opcoes": ["5/36.", "1/6.", "1/12.", "1/9.", "7/36."], "gabarito": 1, "explicacao": "Casos favoráveis: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) = 6 de 36. Probabilidade = 6/36 = 1/6."}, {"materia": "rl", "texto_base": "", "enunciado": "Um produto custava R$ 200,00, teve aumento de 20% e, depois, desconto de 20% sobre o novo preço. O preço final é", "opcoes": ["R$ 208,00.", "R$ 192,00.", "R$ 180,00.", "R$ 200,00.", "R$ 196,00."], "gabarito": 1, "explicacao": "200 × 1,2 = 240; 240 × 0,8 = 192. Aumento e desconto de mesmo percentual não se anulam."}, {"materia": "rl", "texto_base": "", "enunciado": "Em um setor, 3 servidores digitalizam 600 páginas em 4 horas. Mantido o mesmo ritmo, 5 servidores digitalizarão 1.500 páginas em", "opcoes": ["6 horas.", "4 horas.", "10 horas.", "5 horas.", "8 horas."], "gabarito": 0, "explicacao": "Cada servidor faz 600/(3 × 4) = 50 páginas/hora. 5 servidores fazem 250 páginas/hora. 1.500 / 250 = 6 horas."}, {"materia": "rl", "texto_base": "", "enunciado": "Em uma pesquisa com 100 servidores, 60 usam o aplicativo A, 50 usam o aplicativo B e 20 usam os dois. Quantos servidores não usam nenhum dos dois aplicativos?", "opcoes": ["0.", "20.", "15.", "10.", "30."], "gabarito": 3, "explicacao": "A ∪ B = 60 + 50 − 20 = 90. Não usam nenhum: 100 − 90 = 10."}, {"materia": "rl", "texto_base": "", "enunciado": "Na sequência 2, 6, 12, 20, 30, 42, …, o próximo termo é", "opcoes": ["60.", "52.", "56.", "48.", "54."], "gabarito": 2, "explicacao": "As diferenças crescem de 2 em 2 (4, 6, 8, 10, 12, 14). 42 + 14 = 56. Também: n(n + 1), com n = 7 → 56."}, {"materia": "rl", "texto_base": "", "enunciado": "Ana, Bia e Caio ocupam os cargos de analista, técnico e assistente, não necessariamente nessa ordem. Sabe-se que: Ana não é técnica; o assistente é irmão de Bia; Caio não é analista. Então,", "opcoes": ["Ana é assistente, Bia é técnica e Caio é analista.", "Ana é técnica, Bia é analista e Caio é assistente.", "Ana é assistente, Bia é analista e Caio é técnico.", "Ana é analista, Bia é assistente e Caio é técnico.", "Ana é analista, Bia é técnica e Caio é assistente."], "gabarito": 4, "explicacao": "O assistente é irmão de Bia, então é homem e não é Bia: só pode ser Caio. Ana não é técnica, então é analista, e Bia é técnica."}, {"materia": "const", "texto_base": "", "enunciado": "São fundamentos da República Federativa do Brasil, segundo o art. 1º da Constituição Federal:", "opcoes": ["a soberania, a erradicação da pobreza e a defesa da paz.", "a soberania, a cidadania, a dignidade da pessoa humana, os valores sociais do trabalho e da livre iniciativa e o pluralismo político.", "a cidadania, a igualdade entre os Estados e a solução pacífica dos conflitos.", "construir uma sociedade livre, justa e solidária e garantir o desenvolvimento nacional.", "a independência nacional, a prevalência dos direitos humanos, a autodeterminação dos povos, a não intervenção e a igualdade entre os Estados."], "gabarito": 1, "explicacao": "Art. 1º da CF (macete SOCIDIVAPLU). Os objetivos estão no art. 3º, e os princípios das relações internacionais no art. 4º."}, {"materia": "const", "texto_base": "", "enunciado": "De acordo com o art. 5º da Constituição Federal, é correto afirmar que", "opcoes": ["é plena a liberdade de associação para fins lícitos, inclusive a de caráter paramilitar.", "as associações só poderão ser dissolvidas por decisão administrativa motivada.", "a casa é asilo inviolável, podendo-se nela penetrar durante a noite por determinação judicial.", "ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de decreto.", "é livre a manifestação do pensamento, sendo vedado o anonimato."], "gabarito": 4, "explicacao": "Art. 5º, IV. É vedada a associação paramilitar (XVII); a dissolução exige decisão judicial transitada em julgado (XIX); a ordem judicial só se cumpre durante o dia (XI); o princípio da legalidade fala em 'lei' (II)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre os direitos políticos, assinale a alternativa correta.", "opcoes": ["Os estrangeiros podem alistar-se como eleitores após 5 anos de residência ininterrupta no país, desde que alfabetizados e maiores de 18 anos.", "O analfabeto é inelegível, mas não pode votar.", "A idade mínima para Senador é de 30 anos.", "É permitida a cassação de direitos políticos por decisão do Presidente da República.", "O alistamento eleitoral e o voto são facultativos para os maiores de 70 anos e para os maiores de 16 e menores de 18 anos."], "gabarito": 4, "explicacao": "Art. 14, § 1º, II. Estrangeiros não podem se alistar (§ 2º); Senador: 35 anos (§ 3º, VI, a); o analfabeto pode votar (voto facultativo) e é inelegível; é vedada a cassação de direitos políticos (art. 15)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre a organização do Estado, é competência privativa da União legislar sobre", "opcoes": ["direito penal, processual, civil e do trabalho.", "custas dos serviços forenses.", "proteção ao meio ambiente.", "educação, cultura e desporto.", "direito tributário, financeiro, penitenciário e econômico."], "gabarito": 0, "explicacao": "Art. 22, I, da CF. Tributário, financeiro, meio ambiente, educação e custas forenses são de competência concorrente (art. 24)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre a Administração Pública na Constituição Federal, assinale a alternativa correta.", "opcoes": ["O prazo de validade do concurso público será de até 2 anos, prorrogável uma vez, por igual período.", "É garantido ao servidor público civil o direito de greve, independentemente de lei.", "A investidura em cargo em comissão depende de aprovação prévia em concurso público.", "Os cargos públicos são acessíveis apenas a brasileiros natos.", "As funções de confiança podem ser exercidas por qualquer pessoa, mesmo sem vínculo com a Administração."], "gabarito": 0, "explicacao": "Art. 37, III. Os cargos são acessíveis a brasileiros e estrangeiros, na forma da lei (I); as funções de confiança são exclusivas de servidores efetivos (V); a greve será exercida nos termos de lei específica (VII); o cargo em comissão é de livre nomeação (II)."}, {"materia": "const", "texto_base": "", "enunciado": "De acordo com a Constituição Federal, a iniciativa popular de lei federal exige a apresentação de projeto subscrito por, no mínimo,", "opcoes": ["0,5% do eleitorado nacional, distribuído por pelo menos 9 estados.", "1% do eleitorado nacional, distribuído por pelo menos 5 estados, com não menos de 0,3% dos eleitores de cada um deles.", "1% do eleitorado nacional, sem exigência de distribuição.", "5% do eleitorado nacional, distribuído por pelo menos 3 estados, com não menos de 1% dos eleitores de cada um deles.", "10% do eleitorado nacional, distribuído por todos os estados."], "gabarito": 1, "explicacao": "Art. 61, § 2º, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre as medidas provisórias, assinale a alternativa correta.", "opcoes": ["Entram em regime de urgência após 15 dias de sua publicação, trancando a pauta da casa em que estiverem tramitando.", "Podem ser reeditadas na mesma sessão legislativa em que foram rejeitadas.", "Perdem a eficácia, desde a edição, se não forem convertidas em lei em 60 dias, prorrogáveis uma vez por igual período.", "Podem tratar de direito penal e processual penal, em caso de urgência.", "Podem ser editadas por governadores, independentemente de previsão na Constituição estadual."], "gabarito": 2, "explicacao": "Art. 62, § 3º, da CF. É vedada MP sobre direito penal e processual penal (§ 1º, I, b). O STF admite MP estadual se houver previsão na Constituição estadual. O trancamento de pauta ocorre após 45 dias (§ 6º). É vedada a reedição na mesma sessão legislativa (§ 10)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre o Poder Judiciário, assinale a alternativa correta.", "opcoes": ["Os juízes adquirem vitaliciedade após 3 anos de exercício.", "O Superior Tribunal de Justiça compõe-se de 11 Ministros, nomeados pelo Presidente da República entre juízes dos Tribunais Regionais Federais, desembargadores e advogados.", "Os Ministros do STF são nomeados pelo Presidente do Senado.", "O Supremo Tribunal Federal compõe-se de 11 Ministros, escolhidos entre cidadãos com mais de 35 e menos de 70 anos, de notável saber jurídico e reputação ilibada.", "O Conselho Nacional de Justiça tem função jurisdicional."], "gabarito": 3, "explicacao": "Art. 101 da CF (idade máxima alterada pela EC 122/2022). O STJ tem no mínimo 33 Ministros; os do STF são nomeados pelo Presidente da República após aprovação do Senado; o CNJ tem função administrativa; a vitaliciedade vem após 2 anos (art. 95, I)."}, {"materia": "const", "texto_base": "", "enunciado": "São direitos sociais expressamente previstos no art. 6º da Constituição Federal:", "opcoes": ["a livre iniciativa e a livre concorrência.", "a vida, a liberdade, a igualdade, a segurança e a propriedade, garantidas a brasileiros e estrangeiros residentes.", "o sufrágio universal e o voto direto e secreto.", "a nacionalidade e a cidadania.", "a educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer e a segurança."], "gabarito": 4, "explicacao": "O art. 6º lista: educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência social, proteção à maternidade e à infância e assistência aos desamparados."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre os municípios, assinale a alternativa correta.", "opcoes": ["São regidos por lei orgânica, votada em dois turnos, com interstício mínimo de 10 dias, e aprovada por 2/3 dos membros da Câmara Municipal.", "Seus prefeitos são julgados pelo Superior Tribunal de Justiça.", "Têm competência para legislar sobre direito civil, em assuntos de interesse local.", "Podem criar tribunais de contas municipais próprios, desde que a lei orgânica preveja e a Câmara Municipal aprove por 2/3 de seus membros.", "Possuem Poder Judiciário próprio."], "gabarito": 0, "explicacao": "Art. 29 da CF. É vedada a criação de novos tribunais de contas municipais (art. 31, § 4º); municípios não têm Judiciário; direito civil é competência privativa da União; prefeitos são julgados pelo Tribunal de Justiça (art. 29, X)."}, {"materia": "const", "texto_base": "", "enunciado": "A Constituição Federal pode ser emendada mediante proposta, entre outras hipóteses,", "opcoes": ["de 1/3 das Assembleias Legislativas, manifestando-se cada uma pela maioria simples.", "de 1/3, no mínimo, dos membros da Câmara dos Deputados ou do Senado Federal.", "da maioria absoluta dos membros do Congresso Nacional, em sessão conjunta.", "de qualquer cidadão, com apoio de 1% do eleitorado.", "do Supremo Tribunal Federal."], "gabarito": 1, "explicacao": "Art. 60, I a III, da CF: 1/3 da Câmara ou do Senado; Presidente da República; mais da metade das Assembleias Legislativas, cada uma pela maioria relativa. Não há iniciativa popular nem do STF."}, {"materia": "adm", "texto_base": "", "enunciado": "São princípios expressos da Administração Pública no caput do art. 37 da Constituição Federal:", "opcoes": ["supremacia do interesse público, indisponibilidade, legalidade e moralidade.", "impessoalidade, segurança jurídica, eficiência e autotutela.", "legalidade, moralidade, motivação, publicidade e continuidade.", "legalidade, impessoalidade, moralidade, publicidade e eficiência.", "legalidade, razoabilidade, proporcionalidade, publicidade e eficiência."], "gabarito": 3, "explicacao": "LIMPE. Razoabilidade, proporcionalidade, motivação, supremacia, autotutela e continuidade são princípios implícitos ou previstos em leis."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre a organização administrativa, as autarquias", "opcoes": ["exploram atividade econômica em regime de livre concorrência.", "são pessoas jurídicas de direito privado, cuja criação é autorizada por lei, para explorar atividade econômica do Estado.", "são pessoas jurídicas de direito público, criadas por lei específica, para desempenhar atividades típicas de Estado.", "não possuem patrimônio próprio, utilizando os bens do ente que as criou.", "são órgãos públicos despersonalizados da Administração direta."], "gabarito": 2, "explicacao": "Art. 37, XIX, da CF e Decreto-Lei 200/1967, art. 5º, I. Empresas públicas e sociedades de economia mista são de direito privado, com criação autorizada por lei."}, {"materia": "adm", "texto_base": "", "enunciado": "A distribuição de competências dentro de uma mesma pessoa jurídica, com criação de órgãos hierarquizados, denomina-se", "opcoes": ["delegação de serviço público.", "privatização.", "descentralização.", "outorga.", "desconcentração."], "gabarito": 4, "explicacao": "Desconcentração ocorre dentro da mesma pessoa jurídica (cria órgãos). Descentralização transfere a atividade a outra pessoa (por outorga ou delegação)."}, {"materia": "adm", "texto_base": "", "enunciado": "São elementos (requisitos) do ato administrativo:", "opcoes": ["competência, finalidade, forma, motivo e objeto.", "perfeição, validade e eficácia.", "presunção de legitimidade, imperatividade e autoexecutoriedade.", "legalidade, impessoalidade, moralidade, publicidade e eficiência.", "competência, discricionariedade, motivo e tipicidade."], "gabarito": 0, "explicacao": "Lei 4.717/1965, art. 2º (macete COFIFOMOB). Os atributos são presunção de legitimidade, imperatividade, autoexecutoriedade e tipicidade."}, {"materia": "adm", "texto_base": "", "enunciado": "O ato administrativo que apresenta vício sanável de competência ou de forma, sem lesão ao interesse público nem prejuízo a terceiros, pode ser", "opcoes": ["anulado apenas pelo Poder Judiciário.", "convalidado pela própria Administração.", "cassado, por descumprimento de condição.", "revogado, com efeitos retroativos.", "mantido, pois vícios de forma nunca afetam a validade."], "gabarito": 1, "explicacao": "Art. 55 da Lei 9.784/1999. Vícios de competência (não exclusiva) e de forma (não essencial) são, em regra, convalidáveis."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre o poder de polícia, é correto afirmar que", "opcoes": ["consiste na atividade da Administração que limita ou disciplina direitos e liberdades individuais em favor do interesse público.", "é exercido exclusivamente sobre servidores públicos, no âmbito disciplinar.", "é sempre vinculado e nunca autoexecutório.", "é o poder de editar decretos e regulamentos para a fiel execução das leis, sem inovar no ordenamento jurídico.", "não admite a cobrança de taxas."], "gabarito": 0, "explicacao": "Art. 78 do CTN. O poder sobre servidores é o disciplinar; a taxa pode remunerar o poder de polícia (art. 145, II, da CF); há atos discricionários e autoexecutórios; decretos decorrem do poder regulamentar."}, {"materia": "adm", "texto_base": "", "enunciado": "De acordo com a Lei 9.784/1999 (processo administrativo federal), salvo disposição legal específica, o prazo para interposição de recurso administrativo é de", "opcoes": ["15 dias, contados da decisão.", "5 dias úteis, contados da publicação da decisão no Diário Oficial.", "30 dias, contados da intimação.", "10 dias, contados da ciência ou divulgação oficial da decisão.", "48 horas, contadas da ciência."], "gabarito": 3, "explicacao": "Art. 59 da Lei 9.784/1999. A decisão do recurso deve sair em até 30 dias, prorrogáveis por igual período (§§ 1º e 2º)."}, {"materia": "adm", "texto_base": "", "enunciado": "Segundo a Lei 9.784/1999, o direito da Administração de anular os atos administrativos de que decorram efeitos favoráveis para os destinatários decai em", "opcoes": ["2 anos, contados da ciência do vício pela autoridade competente.", "nunca, pois a Administração pode anular seus atos a qualquer tempo.", "10 anos, em qualquer caso.", "5 anos, contados da data em que foram praticados, salvo comprovada má-fé.", "3 anos, contados da publicação."], "gabarito": 3, "explicacao": "Art. 54 da Lei 9.784/1999."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre a responsabilidade civil do Estado, assinale a alternativa correta.", "opcoes": ["O direito de regresso contra o agente independe de dolo ou culpa, pois a responsabilidade do Estado é objetiva e se transmite ao servidor que causou o dano.", "O Estado responde objetivamente por qualquer dano, sem admitir excludentes.", "A vítima deve sempre comprovar a culpa do agente público.", "A responsabilidade objetiva não se aplica a usuários do serviço público.", "As pessoas jurídicas de direito privado prestadoras de serviço público respondem objetivamente pelos danos que seus agentes causarem a terceiros."], "gabarito": 4, "explicacao": "Art. 37, § 6º, da CF. Admitem-se excludentes (culpa exclusiva da vítima, caso fortuito, força maior); o regresso exige dolo ou culpa; o STF aplica a responsabilidade objetiva a usuários e não usuários (RE 591.874)."}, {"materia": "adm", "texto_base": "", "enunciado": "Na Lei 14.133/2021, é hipótese de licitação dispensável (dispensa de licitação)", "opcoes": ["a aquisição de bem fornecido por produtor exclusivo.", "a contratação de obras e serviços de engenharia de valor inferior ao limite fixado na lei.", "a contratação de artista consagrado pela crítica ou pela opinião pública.", "a contratação de serviço técnico especializado de natureza predominantemente intelectual com profissional de notória especialização.", "a aquisição de imóvel cujas características tornem necessária sua escolha."], "gabarito": 1, "explicacao": "Dispensa por valor: art. 75, I, da Lei 14.133/2021. As demais hipóteses são de inexigibilidade (art. 74), por inviabilidade de competição."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre os bens públicos, é correto afirmar que", "opcoes": ["os bens públicos não estão sujeitos a usucapião.", "os bens públicos podem ser penhorados em execução comum.", "praças e ruas são exemplos de bens dominicais.", "os bens de uso comum do povo podem ser alienados livremente.", "os bens dominicais são inalienáveis em qualquer hipótese."], "gabarito": 0, "explicacao": "Arts. 183, § 3º, e 191, parágrafo único, da CF, e art. 102 do CC. Bens de uso comum e especiais são inalienáveis enquanto afetados; dominicais podem ser alienados, observada a lei; bens públicos são impenhoráveis; praças e ruas são de uso comum."}, {"materia": "inf", "texto_base": "", "enunciado": "No Microsoft Excel, a fórmula =SE(A1>=7;\"Aprovado\";\"Reprovado\"), com A1 igual a 7, retorna", "opcoes": ["Aprovado", "VERDADEIRO", "7", "#NOME?", "Reprovado"], "gabarito": 0, "explicacao": "A condição A1 >= 7 é verdadeira (7 é maior ou igual a 7), então a função retorna o 2º argumento: 'Aprovado'."}, {"materia": "inf", "texto_base": "", "enunciado": "No Excel, ao copiar a fórmula =A1*$B$1, digitada na célula C1, para a célula C3, a fórmula resultante será", "opcoes": ["=A3*$B$3", "=C3*$B$1", "=A3*$B$1", "=A1*$B$1", "=A3*B3"], "gabarito": 2, "explicacao": "A referência relativa A1 ajusta-se 2 linhas abaixo (A3); a absoluta $B$1 não muda."}, {"materia": "inf", "texto_base": "", "enunciado": "Um programa malicioso que se propaga automaticamente pelas redes, explorando vulnerabilidades, sem precisar ser anexado a outro arquivo nem executado pelo usuário, é o", "opcoes": ["adware.", "spyware.", "cavalo de troia.", "vírus.", "worm."], "gabarito": 4, "explicacao": "O worm se replica sozinho pela rede. O vírus depende de um hospedeiro e de execução; o cavalo de troia se disfarça de programa legítimo."}, {"materia": "inf", "texto_base": "", "enunciado": "Sobre computação em nuvem, assinale a alternativa que relaciona corretamente o modelo de serviço ao exemplo.", "opcoes": ["IaaS: aplicativo de mensagens instalado no celular.", "IaaS (Infraestrutura como Serviço): uso de um editor de planilhas on-line.", "PaaS (Plataforma como Serviço): uso de pen drive para guardar arquivos.", "SaaS: aluguel de servidores virtuais para instalar o próprio sistema operacional e os programas da empresa.", "SaaS (Software como Serviço): uso de e-mail e editor de textos pelo navegador, sem instalar o programa."], "gabarito": 4, "explicacao": "SaaS: aplicação pronta pela internet. PaaS: ambiente para desenvolver e hospedar aplicações. IaaS: infraestrutura virtual (servidores, armazenamento, rede)."}, {"materia": "inf", "texto_base": "", "enunciado": "No Windows, o atalho de teclado que bloqueia a sessão do usuário rapidamente é", "opcoes": ["Ctrl + Esc.", "Windows + E.", "Windows + L.", "Alt + F4.", "Windows + D."], "gabarito": 2, "explicacao": "Windows + L bloqueia o computador. Windows + D mostra a área de trabalho; Windows + E abre o Explorador de Arquivos; Alt + F4 fecha a janela ativa."}, {"materia": "inf", "texto_base": "", "enunciado": "No Microsoft Word, o recurso que permite criar automaticamente um sumário com base nos estilos de título aplicados ao texto encontra-se na guia", "opcoes": ["Inserir.", "Exibir.", "Referências.", "Layout.", "Revisão."], "gabarito": 2, "explicacao": "Referências > Sumário. O sumário automático usa os estilos Título 1, Título 2 etc."}, {"materia": "inf", "texto_base": "", "enunciado": "Em um endereço de e-mail como servidor@orgao.gov.br, a parte “orgao.gov.br” corresponde", "opcoes": ["ao protocolo de envio.", "à porta de comunicação do servidor.", "ao nome do usuário.", "ao endereço IP do computador do usuário remetente.", "ao domínio do provedor do serviço de e-mail."], "gabarito": 4, "explicacao": "O que vem depois da @ é o domínio; antes, o nome do usuário (caixa postal)."}, {"materia": "inf", "texto_base": "", "enunciado": "Sobre o navegador de internet, a navegação anônima (privada)", "opcoes": ["impede que o provedor de internet e o empregador saibam quais sites foram acessados, pois apaga os registros também nos servidores desses intermediários, e não apenas no computador.", "criptografa todos os dados transmitidos, substituindo o HTTPS.", "oculta o endereço IP do usuário para todos os sites.", "não salva o histórico, os cookies e os dados de formulários no computador depois que a janela é fechada, mas não torna o usuário invisível para o provedor ou os sites visitados.", "bloqueia automaticamente todos os vírus e programas maliciosos."], "gabarito": 3, "explicacao": "A navegação privada só evita que dados fiquem salvos localmente. Provedor, empregador e sites ainda podem identificar o acesso."}, {"materia": "inf", "texto_base": "", "enunciado": "Na segurança da informação, o princípio que garante que a informação só seja acessada por pessoas autorizadas é a", "opcoes": ["integridade.", "irretratabilidade.", "confidencialidade.", "autenticidade.", "disponibilidade."], "gabarito": 2, "explicacao": "Confidencialidade: acesso só a autorizados. Integridade: não alteração indevida. Disponibilidade: acesso quando necessário."}, {"materia": "inf", "texto_base": "", "enunciado": "No Excel, a função que conta quantas células de um intervalo não estão vazias é", "opcoes": ["CONT.SE sem critério.", "CONT.VALORES.", "CONTAR.VAZIO.", "CONT.NÚM.", "SOMA."], "gabarito": 1, "explicacao": "CONT.VALORES conta células não vazias (texto, números etc.). CONT.NÚM conta só números; CONTAR.VAZIO conta as vazias."}, {"materia": "inf", "texto_base": "", "enunciado": "O ataque em que o criminoso sequestra os dados da vítima, criptografando-os, e exige pagamento (geralmente em criptomoeda) para liberá-los é o", "opcoes": ["phishing.", "sniffing.", "ransomware.", "spoofing.", "keylogger."], "gabarito": 2, "explicacao": "Ransomware criptografa dados e cobra resgate. Phishing engana para obter dados; spoofing falsifica a origem; sniffing captura tráfego; keylogger registra o que é digitado."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('geral', date '2026-11-22', 'Simulado 1 · Geral', 'FGV', 180, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado 1 · Geral já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.trilha, s.data - 1 as abre_sabado, s.data as fecha_domingo, s.titulo, s.estilo, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.data = date '2026-11-22' group by s.id order by s.trilha;
